//! Support for actually generating a JS function shim.
//!
//! This `Builder` type is used to generate JS function shims which sit between
//! exported functions, table elements, imports, etc. All function shims
//! generated by `wasm-bindgen` run through this type.

use crate::descriptor::{SeqValue, VectorKind};
use crate::js::{Context, IdentScope, MemView};
use crate::wit::{
    Adapter, AdapterId, AdapterKind, AdapterType, AuxFunctionArgumentData, ClosureDtor, Instruction,
};
use crate::wit::{InstructionData, OptionKind};
use crate::OutputMode;
use anyhow::{bail, Error};
use std::borrow::Cow;
use std::collections::{HashMap, HashSet};
use std::fmt;
use std::fmt::Write;
use walrus::{Module, ValType};
use wasm_bindgen_shared::identifier::is_valid_ident;

/// A one-size-fits-all builder for processing WebIDL bindings and generating
/// JS.
pub struct Builder<'a, 'b> {
    /// Parent context used to expose helper functions and such.
    pub cx: &'a mut Context<'b>,
    /// Whether or not this is building a constructor for a Rust class, and if
    /// so what class it's constructing.
    constructor: Option<String>,
    /// Whether or not this is building a method of a Rust class instance, and
    /// whether or not the method consumes `self` or not.
    method: Option<bool>,
    /// If building a method, the class that defines it. Used to dispatch the
    /// `this` pointer through the inheritance-aware per-class field
    /// (`this.__wbg_ptr_<OwnClass>`) when the class participates in an
    /// `extends` chain.
    method_class: Option<String>,
    /// Whether this is a classless this function (receives JS `this` as first param)
    classless_this: bool,
    /// Whether this invokes a closure, whose first two arguments are the
    /// closure's state from the glue rather than values from user JS.
    closure_invoke: bool,
    /// Whether or not we're catching exceptions from the main function
    /// invocation. Currently only used for imports.
    catch: bool,
    /// Whether or not we're logging the error coming out of this intrinsic
    log_error: bool,
}

/// Helper struct used to create JS to process all instructions in an adapter
/// function.
pub struct JsBuilder<'a, 'b> {
    /// General context for building JS, used to manage intrinsic names, exposed
    /// JS functions, etc.
    cx: &'a mut Context<'b>,

    /// A debug name for the function being generated, used for error messages
    debug_name: &'a str,

    /// The statements of the function body built so far.
    prelude: Vec<Stmt>,

    /// Code which should go before the `try {` in a try-finally block.
    pre_try: String,

    /// JS code to execute in a `finally` block in case any exceptions happen.
    finally: String,

    /// The instruction being translated.
    instr: InstrState,

    /// What the arguments have allocated so far, until Rust is called.
    guard: Option<ArgGuard>,

    /// An index used to manage allocation of temporary indices, used to name
    /// variables to ensure nothing clashes with anything else.
    tmp: usize,

    /// The arguments to the adapter, which the `arg.get` instruction pushes.
    args: Vec<Value>,

    /// Identifiers bound in the function body, which the arguments must not
    /// shadow.
    locals: HashSet<String>,

    /// The Wasm interface types "stack". Expressions that aren't pure are
    /// bound in the `prelude` and pushed as locals.
    stack: Vec<Value>,
}

/// A statement of the function body. It is `pure` when it reads only the JS
/// arguments and does nothing but throw or bind a local, so it can run ahead
/// of any allocation.
struct Stmt {
    pure: bool,
    kind: StmtKind,
}

/// Bindings are kept apart from their text so a `try` wrapped around them can
/// lift them out as a `let`.
enum StmtKind {
    Raw(String),
    /// `keyword` declares the binding, or is `None` once lifted.
    Decl {
        keyword: Option<&'static str>,
        name: String,
        expr: String,
    },
}

fn render(stmts: &[Stmt]) -> String {
    let mut code = String::new();
    for stmt in stmts {
        match &stmt.kind {
            StmtKind::Raw(text) => code.push_str(text),
            StmtKind::Decl {
                keyword: Some(keyword),
                name,
                expr,
            } => writeln!(code, "{keyword} {name} = {expr};").unwrap(),
            StmtKind::Decl {
                keyword: None,
                name,
                expr,
            } => writeln!(code, "{name} = {expr};").unwrap(),
        }
    }
    code
}

/// What the instruction being translated has done so far, which decides
/// whether its statements, and the values it pushes, depend on the prelude.
#[derive(Default)]
struct InstrState {
    /// Where the prelude stood when it began.
    start: usize,
    /// Whether it read a local, or an expression over one.
    reads_local: bool,
    /// Whether it bound a local.
    binds_local: bool,
    /// Whether it allocated or registered a `finally`.
    effects: bool,
    /// Where the prelude stood at its last allocation.
    allocated_at: Option<usize>,
}

/// A value on the stack, with how it came to be, which decides what the call
/// into Wasm must do before it can take it.
#[derive(Clone)]
enum Value {
    /// A JS argument as the caller passed it.
    Param(String),
    /// A local the prelude bound.
    Local(String),
    /// An expression that throws neither when evaluated nor when Wasm
    /// converts it to its parameter type.
    Safe(String),
    /// A `Safe` expression that allocates when evaluated, such as an owned
    /// `JsValue` put in the externref table or on the JS heap. It's
    /// evaluated in the call, where nothing Wasm converts may throw after it.
    Alloc(String),
    /// Any other expression; `pure` when it reads only the JS arguments, so
    /// it can be evaluated before anything is allocated.
    Expr { expr: String, pure: bool },
}

impl Value {
    fn expr(&self) -> &str {
        match self {
            Value::Param(e)
            | Value::Local(e)
            | Value::Safe(e)
            | Value::Alloc(e)
            | Value::Expr { expr: e, .. } => e,
        }
    }

    fn into_expr(self) -> String {
        match self {
            Value::Param(e)
            | Value::Local(e)
            | Value::Safe(e)
            | Value::Alloc(e)
            | Value::Expr { expr: e, .. } => e,
        }
    }
}

impl fmt::Display for Value {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.expr())
    }
}

/// What the arguments have allocated so far, to release should JS throw
/// before Rust is called to take them. A throw runs no destructors, and the
/// arguments are converted in order, so a later argument that JS rejects, or
/// that Wasm fails to convert such as a number passed for an `i64`, would
/// leak the earlier ones.
struct ArgGuard {
    /// Where the prelude stood before the first allocating instruction, and
    /// how many statements it emitted up to its allocation.
    start: usize,
    first: usize,
    /// Whether an allocating instruction went on after allocating, such as
    /// an encoded slice's element loop, which may throw.
    tail: bool,
    /// Statements releasing each allocation, in allocation order.
    releases: Vec<String>,
}

pub struct JsFunction {
    pub code: String,
    pub ts_sig: String,
    pub js_doc: String,
    pub ts_doc: String,
    pub ts_arg_tys: Vec<String>,
    pub ts_ret_ty: Option<String>,
    pub ts_refs: HashSet<TsReference>,
    /// Whether this function has a single optional argument.
    ///
    /// If the function is a setter, that means that the field it sets is optional.
    pub might_be_optional_field: bool,
    pub catch: bool,
    pub log_error: bool,
    /// True when the generated JS function body uses `await` (JSPI exports that
    /// return a value).  The function definition must then be prefixed with `async`.
    pub jspi_async: bool,
}

/// A references to an (likely) exported symbol used in TS type expression.
///
/// Right now, only string enum and dynamic unions require this type of analysis.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum TsReference {
    StringEnum(String),
    DynamicUnion(String),
}

/// Whether and how to guard an export call against instance termination.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ExportGuard {
    /// No guard wrapping needed.
    None,
    /// Wrap with termination guard and try-catch for panic=abort with error handling.
    Abort,
    /// Wrap with just termination guard for schedule_reinit() support.
    GuardOnly,
}

fn wrap_try_catch(call: &str) -> String {
    format!(
        "\
        __wbg_call_guard();
        try {{
            {call};
        }} catch(e) {{
            __wbg_handle_catch(e);
        }}
        "
    )
}

fn wrap_call_guard(call: &str) -> String {
    format!(
        "\
        __wbg_call_guard();
        {call};
        "
    )
}

pub fn maybe_wrap_export_call(call: &str, guard: ExportGuard) -> String {
    match guard {
        ExportGuard::Abort => wrap_try_catch(call),
        ExportGuard::GuardOnly => wrap_call_guard(call),
        ExportGuard::None => format!("{call};"),
    }
}

/// Sentinel used by the f64-ABI `Option` paths to represent `None`. Must not
/// collide with any valid payload (including i64/u64 on wasm64 via f64).
const F64_OPTION_SENTINEL: &str = "Number.MAX_SAFE_INTEGER";
/// `Nullable::Null` over the `f64` ABI, below the `undefined` sentinel.
const F64_NULL_SENTINEL: &str = "Number.MAX_SAFE_INTEGER - 1";
/// `None` and `Nullable::Null` over the small-integer ABI.
const U32_OPTION_SENTINEL: &str = "0xFFFFFF";
const U32_NULL_SENTINEL: &str = "0xFFFFFE";
/// The handle of `null`. A slice with a null pointer carries a JS handle in
/// its length, as an interned string does, and `0` is `undefined`, so
/// `Nullable::Null` is this length and the cached-string reader needs no
/// change.
const NULL_HANDLE: usize = super::INITIAL_HEAP_OFFSET + 1;

/// Identifiers a function body references without going through `Context`:
/// JS globals and fixed module-scope names of the glue. Arguments never take
/// these names.
const BODY_GLOBALS: &[&str] = &[
    "undefined",
    "arguments",
    "Array",
    "BigInt",
    "Error",
    "Math",
    "Number",
    "Object",
    "String",
    "Symbol",
    "TypeError",
    "WebAssembly",
    "WASM_VECTOR_LEN",
    "__wbg_instance_id",
    "__wbgSuperSkip",
    "__wbg_call_guard",
    "__wbg_handle_catch",
];

impl<'a, 'b> Builder<'a, 'b> {
    pub fn new(cx: &'a mut Context<'b>) -> Builder<'a, 'b> {
        Builder {
            log_error: false,
            cx,
            constructor: None,
            method: None,
            method_class: None,
            classless_this: false,
            closure_invoke: false,
            catch: false,
        }
    }

    pub fn method(&mut self, consumed: bool) {
        self.method = Some(consumed);
    }

    /// Record the class name that owns the method being built. Used to
    /// route `this.__wbg_ptr` lookups through the per-class inheritance
    /// field when the class extends (or is extended by) another.
    pub fn method_class(&mut self, class: &str) {
        self.method_class = Some(class.to_string());
    }

    pub fn classless_this(&mut self) {
        self.classless_this = true;
    }

    pub fn closure_invoke(&mut self) {
        self.closure_invoke = true;
    }

    pub fn constructor(&mut self, class: &str) {
        self.constructor = Some(class.to_string());
    }

    pub fn catch(&mut self, catch: bool) {
        self.catch = catch;
    }

    pub fn log_error(&mut self, log: bool) {
        self.log_error = log;
    }

    pub fn process(
        &mut self,
        adapter: &Adapter,
        instructions: &[InstructionData],
        args_data: &Option<Vec<AuxFunctionArgumentData>>,
        asyncness: bool,
        variadic: bool,
        generate_jsdoc: bool,
        debug_name: &str,
        ret_ty_override: &Option<String>,
        ret_desc: &Option<String>,
    ) -> Result<JsFunction, Error> {
        if !self.cx.unwind_enabled
            && self
                .cx
                .aux
                .imports_with_assert_no_shim
                .contains(&adapter.id)
        {
            bail!("generating a shim for something asserted to have no shim");
        }

        let mut params = adapter.params.iter();
        let mut function_args = Vec::new();
        let mut arg_tys = Vec::new();

        // Inheritance constructor wiring (computed BEFORE JsBuilder::new
        // borrows `self.cx` mutably).
        //
        // JS forbids a subclass constructor from touching `this` before it
        // invokes `super(...)`. Our emitted constructor body does write
        // `this.__wbg_ptr` (see the `RustFromI32` lowering further below),
        // so a subclass constructor must begin with `super(...)`.
        //
        // A subclass's ctor also allocates its OWN Rust struct and wants to
        // end up with only the child's pointer on `this`. If `super(...)`
        // invoked the parent's user ctor it would allocate a spurious
        // orphan parent instance. We avoid that with a shared module-level
        // sentinel (emitted once up front in `generate()`): subclass calls
        // `super(__wbgSuperSkip)`, and every user ctor checks for the
        // sentinel and returns early.
        //
        // Top-level (non-subclass) ctors can safely `return` before doing
        // any `this` access. Subclass ctors must do super() first, then the
        // sentinel check — which is still valid because after super() the
        // `this` binding is initialized, so an empty `return;` is legal.
        let (ctor_is_subclass, ctor_needs_sentinel_check) = match &self.constructor {
            Some(ctor_class) => {
                let resolved = self.cx.resolve_class_name(ctor_class).to_string();
                let is_subclass = self
                    .cx
                    .exported_classes
                    .get(&resolved)
                    .and_then(|c| c.extends.as_ref())
                    .is_some();
                (is_subclass, self.cx.has_super_skip_sentinel())
            }
            None => (false, false),
        };

        // Route the `this` pointer through a per-class field when the
        // method's class participates in an `extends` chain. Every class
        // in a chain stores `this.__wbg_ptr_<OwnClass>` alongside
        // `this.__wbg_ptr`; the unqualified slot mirrors the own-class
        // pointer so callers that read it directly resolve correctly.
        //
        // For `self`-by-value methods, also compute a subclass-dispatch
        // guard: a Rust descendant reaching this method via the JS
        // prototype chain would call `this.__destroy_into_raw()` on the
        // descendant (returning the descendant pointer) and hand it to
        // this method's parent wasm shim — type-confused free / UB. The
        // guard rejects by comparing the leaf `this.__wbg_ptr` against
        // the per-class slot `this.__wbg_ptr_<Class>`. For the actual
        // class instance (or a user-written JS-only subclass that doesn't
        // add a wasm-bindgen layer) those slots agree; for a Rust
        // descendant the per-class slot holds the upcasted ancestor
        // pointer and differs from `__wbg_ptr`, so the call throws.
        let (this_ptr_expr, consumes_self_subclass_guard) = match &self.method_class {
            Some(method_class) => {
                let resolved = self.cx.resolve_class_name(method_class).to_string();
                let cls = self.cx.exported_classes.get(&resolved);
                if cls.is_some_and(|c| c.participates_in_inheritance) {
                    let identifier = cls.map(|c| c.identifier.clone()).unwrap_or(resolved);
                    let guard = format!(
                        "if (this.__wbg_ptr !== this.__wbg_ptr_{identifier}) {{ \
                            throw new TypeError('{identifier}: a `self`-by-value method cannot be invoked through subclass prototype dispatch'); \
                        }}"
                    );
                    (format!("this.__wbg_ptr_{identifier}"), Some(guard))
                } else {
                    ("this.__wbg_ptr".to_string(), None)
                }
            }
            None => ("this.__wbg_ptr".to_string(), None),
        };

        // If this is a method then we're generating this as part of a class
        // method, so the leading parameter is the this pointer stored on
        // the JS object, so synthesize that here.
        let receiver = if let Some(consumes_self) = self.method {
            let _ = params.next();
            Some(if consumes_self {
                Receiver::Consumed
            } else {
                Receiver::Expr(this_ptr_expr)
            })
        } else if self.classless_this {
            let _ = params.next();
            Some(Receiver::Expr("this".to_string()))
        } else {
            None
        };
        for (i, param) in params.enumerate() {
            let arg = match args_data {
                Some(list) => list[i].clone(),
                None => AuxFunctionArgumentData {
                    name: format!("arg{i}"),
                    ty_override: None,
                    optional: false,
                    desc: None,
                },
            };
            function_args.push(arg);
            arg_tys.push(param);
        }

        // JSPI exports `await` the promising call inside an `async` JS wrapper
        // so that return-value post-processing and deferred frees in the
        // `finally` block run only after the fiber has fully completed.  We
        // record this before the instruction loop so `JsFunction` can carry it.
        let jspi_async = self.cx.current_adapter_jspi;

        // Argument names come from Rust, so they may shadow an identifier the
        // body binds or references (`wasm`, `ret`, a class, ...). Which ones
        // the body uses is only known once it's generated, so generate it
        // with the given names, and if any is shadowed, rename those away
        // from everything the body uses and generate it again.
        let mut js_names: Vec<String> = function_args.iter().map(|a| a.name.clone()).collect();
        let body = BodyParams {
            receiver: receiver.as_ref(),
            ctor_is_subclass,
            ctor_needs_sentinel_check,
            consumes_self_subclass_guard: consumes_self_subclass_guard.as_deref(),
            method_class: self.method_class.as_deref(),
            closure_invoke: self.closure_invoke,
            constructor: &self.constructor,
            adapter,
            instructions,
            debug_name,
        };
        let mut js = body.generate(self.cx, &js_names, &mut self.log_error)?;
        if js_names.iter().any(|name| js.shadows(name)) {
            let mut scope = js.scope();
            for name in js_names.iter().filter(|name| !js.shadows(name)) {
                scope.reserve(name);
            }
            for name in js_names.iter_mut().filter(|name| js.shadows(name)) {
                *name = scope.generate(name);
            }
            js = body.generate(self.cx, &js_names, &mut self.log_error)?;
        }
        let js_function_args = function_args
            .iter()
            .zip(&js_names)
            .map(|(arg, name)| AuxFunctionArgumentData {
                name: name.clone(),
                ..arg.clone()
            })
            .collect::<Vec<_>>();

        let mut code = String::new();
        code.push('(');
        for (i, name) in js_names.iter().enumerate() {
            if i != 0 {
                code.push_str(", ");
            }

            if variadic && i == js_names.len() - 1 {
                code.push_str("...");
            }

            code.push_str(name);
        }
        code.push_str(") {\n");

        let prelude = render(&js.prelude);
        let call = if !js.finally.is_empty() {
            format!(
                "{pre_try}try {{\n{prelude}}} finally {{\n{finally}}}\n",
                pre_try = js.pre_try,
                finally = js.finally
            )
        } else {
            js.pre_try + &prelude
        };

        // Generate a try/catch block in debug mode which handles unexpected and
        // unhandled exceptions, typically used on imports. This currently just
        // logs what happened, but keeps the exception being thrown to propagate
        // elsewhere.
        if self.log_error {
            js.cx.expose_log_error();
        }

        code.push_str(&call);
        code.push('}');

        // Rust Structs' fields converted into Getter and Setter functions before
        // we decode them from webassembly, finding if a function is a field
        // should start from here. Struct fields(Getter) only have one arg, and
        // this is the clue we can infer if a function might be a field.
        let mut might_be_optional_field = false;
        // For JSPI exports, the return type should be `Promise<T>` in TypeScript
        // (just like async functions). We pass the OR of the two flags.
        let ts_asyncness = asyncness || self.cx.current_adapter_jspi;
        let (ts_sig, ts_arg_tys, ts_ret_ty, ts_refs) = self.typescript_signature(
            &function_args,
            &arg_tys,
            &adapter.inner_results,
            &mut might_be_optional_field,
            ts_asyncness,
            variadic,
            ret_ty_override,
        );
        let js_doc = if generate_jsdoc {
            self.js_doc_comments(
                &js_function_args,
                &arg_tys,
                &ts_ret_ty,
                variadic,
                ret_ty_override,
                ret_desc,
            )
        } else {
            String::new()
        };

        // generate ts_doc
        // ts doc is slightly different than js doc, where there is no
        // arguments types followed after @param tag, as well as no special
        // casings for arguments names such as "@param {string} [arg]" that
        // tags the argument as optional, for ts doc we only need arg names
        // and rest are just derived from function ts signature
        let ts_doc = self.ts_doc_comments(&function_args, ret_desc);

        Ok(JsFunction {
            code,
            ts_sig,
            js_doc,
            ts_doc,
            ts_arg_tys,
            ts_ret_ty,
            ts_refs,
            might_be_optional_field,
            catch: self.catch,
            log_error: self.log_error,
            jspi_async,
        })
    }

    /// Returns the typescript signature of the binding that this has described.
    /// This is used to generate all the TypeScript definitions later on.
    ///
    /// Note that the TypeScript returned here is just the argument list and the
    /// return value, it doesn't include the function name in any way.
    fn typescript_signature(
        &self,
        args_data: &[AuxFunctionArgumentData],
        arg_tys: &[&AdapterType],
        result_tys: &[AdapterType],
        might_be_optional_field: &mut bool,
        asyncness: bool,
        variadic: bool,
        ret_ty_override: &Option<String>,
    ) -> (String, Vec<String>, Option<String>, HashSet<TsReference>) {
        // Build up the typescript signature as well
        let mut omittable = true;
        let mut ts_args = Vec::new();
        let mut ts_arg_tys = Vec::new();
        let mut ts_refs = HashSet::new();
        for (
            AuxFunctionArgumentData {
                name,
                ty_override,
                optional,
                ..
            },
            ty,
        ) in args_data.iter().zip(arg_tys).rev()
        {
            // In TypeScript, we can mark optional parameters as omittable
            // using the `?` suffix, but only if they're not followed by
            // non-omittable parameters. Therefore iterate the parameter list
            // in reverse and stop using the `?` suffix for optional params as
            // soon as a non-optional parameter is encountered.
            let mut arg = name.to_string();
            let mut ts = String::new();
            if let Some(v) = ty_override {
                omittable = false;
                if *optional {
                    arg.push('?');
                }
                arg.push_str(": ");
                ts.push_str(v);
            } else {
                match ty {
                    AdapterType::Option { ty, kind } if omittable && kind.accepts_undefined() => {
                        // e.g. `foo?: string | null`
                        arg.push_str("?: ");
                        adapter2ts(
                            ty,
                            TypePosition::Argument,
                            &mut ts,
                            Some(&mut ts_refs),
                            &self.cx.qualified_to_identifier,
                            self.cx.config.ts_typed_array_buffers,
                        );
                        if kind.accepts_null() {
                            ts.push_str(" | null");
                        }
                    }
                    ty => {
                        adapter2ts(
                            ty,
                            TypePosition::Argument,
                            &mut ts,
                            Some(&mut ts_refs),
                            &self.cx.qualified_to_identifier,
                            self.cx.config.ts_typed_array_buffers,
                        );
                        omittable = false;
                        arg.push_str(": ");
                    }
                }
            }
            arg.push_str(&ts);
            ts_arg_tys.push(ts);
            ts_args.push(arg);
        }
        ts_args.reverse();
        ts_arg_tys.reverse();
        let mut ts = String::from("(");
        if variadic {
            if let Some((last, non_variadic_args)) = ts_args.split_last() {
                ts.push_str(&non_variadic_args.join(", "));
                if !non_variadic_args.is_empty() {
                    ts.push_str(", ");
                }
                ts.push_str((String::from("...") + last).as_str())
            }
        } else {
            ts.push_str(&ts_args.join(", "));
        };
        ts.push(')');

        // If this function is an optional field's setter, it should have only
        // one arg, and omittable should be `true`.
        if ts_args.len() == 1 && omittable {
            *might_be_optional_field = true;
        }

        // Constructors have no listed return type in typescript
        let mut ts_ret = None;
        if self.constructor.is_none() {
            ts.push_str(": ");
            let mut ret = String::new();
            if let Some(v) = &ret_ty_override {
                ret.push_str(v);
            } else {
                match result_tys.len() {
                    0 => ret.push_str("void"),
                    1 => adapter2ts(
                        &result_tys[0],
                        TypePosition::Return,
                        &mut ret,
                        Some(&mut ts_refs),
                        &self.cx.qualified_to_identifier,
                        self.cx.config.ts_typed_array_buffers,
                    ),
                    _ => ret.push_str("[any]"),
                }
            }
            if asyncness {
                ret = format!("Promise<{ret}>");
            }
            ts.push_str(&ret);
            ts_ret = Some(ret);
        }
        (ts, ts_arg_tys, ts_ret, ts_refs)
    }

    /// Returns a helpful JS doc comment which lists types for all parameters
    /// and the return value.
    fn js_doc_comments(
        &self,
        args_data: &[AuxFunctionArgumentData],
        arg_tys: &[&AdapterType],
        ts_ret: &Option<String>,
        variadic: bool,
        ret_ty_override: &Option<String>,
        ret_desc: &Option<String>,
    ) -> String {
        let (variadic_arg, fn_arg_names) = match args_data.split_last() {
            Some((last, args)) if variadic => (Some(last), args),
            _ => (None, args_data),
        };

        let mut omittable = true;
        let mut js_doc_args = Vec::new();

        for (
            AuxFunctionArgumentData {
                name,
                ty_override,
                optional,
                desc,
            },
            ty,
        ) in fn_arg_names.iter().zip(arg_tys).rev()
        {
            let mut arg = "@param {".to_string();

            if let Some(v) = ty_override {
                omittable = false;
                arg.push_str(v);
                arg.push_str("} ");
                if *optional {
                    // Use [name] syntax for optional parameters
                    arg.push('[');
                    arg.push_str(name);
                    arg.push(']');
                } else {
                    arg.push_str(name);
                }
            } else {
                match ty {
                    AdapterType::Option { ty, kind } if omittable && kind.accepts_undefined() => {
                        adapter2ts(
                            ty,
                            TypePosition::Argument,
                            &mut arg,
                            None,
                            &self.cx.qualified_to_identifier,
                            self.cx.config.ts_typed_array_buffers,
                        );
                        if kind.accepts_null() {
                            arg.push_str(" | null");
                        }
                        arg.push_str("} ");
                        arg.push('[');
                        arg.push_str(name);
                        arg.push(']');
                    }
                    _ => {
                        omittable = false;
                        adapter2ts(
                            ty,
                            TypePosition::Argument,
                            &mut arg,
                            None,
                            &self.cx.qualified_to_identifier,
                            self.cx.config.ts_typed_array_buffers,
                        );
                        arg.push_str("} ");
                        arg.push_str(name);
                    }
                }
            }
            // append description
            if let Some(v) = desc {
                arg.push_str(" - ");
                arg.push_str(v);
            }
            arg.push('\n');
            js_doc_args.push(arg);
        }

        let mut ret: String = js_doc_args.into_iter().rev().collect();

        if let (
            Some(AuxFunctionArgumentData {
                name,
                ty_override,
                optional: _,
                desc,
            }),
            Some(ty),
        ) = (variadic_arg, arg_tys.last())
        {
            ret.push_str("@param {...");
            if let Some(v) = ty_override {
                ret.push_str(v);
            } else {
                adapter2ts(
                    ty,
                    TypePosition::Argument,
                    &mut ret,
                    None,
                    &self.cx.qualified_to_identifier,
                    self.cx.config.ts_typed_array_buffers,
                );
            }
            ret.push_str("} ");
            ret.push_str(name);

            // append desc
            if let Some(v) = desc {
                ret.push_str(" - ");
                ret.push_str(v);
            }
            ret.push('\n');
        }
        if let Some(ts) = ret_ty_override.as_ref().or(ts_ret.as_ref()) {
            // skip if type is void and there is no description
            if ts != "void" || ret_desc.is_some() {
                ret.push_str(&format!("@returns {{{ts}}}"));
            }
            // append return description
            if let Some(v) = ret_desc {
                ret.push(' ');
                ret.push_str(v);
            }
        }
        ret
    }

    /// Returns a helpful TS doc comment which lists all parameters and
    /// the return value descriptions.
    fn ts_doc_comments(
        &self,
        args_data: &[AuxFunctionArgumentData],
        ret_desc: &Option<String>,
    ) -> String {
        let mut ts_doc = String::new();
        // ofc we dont need arg type for ts doc, only arg name
        for AuxFunctionArgumentData { name, desc, .. } in args_data.iter() {
            ts_doc.push_str("@param ");
            ts_doc.push_str(name);

            // append desc
            if let Some(v) = desc {
                ts_doc.push_str(" - ");
                ts_doc.push_str(v);
            }
            ts_doc.push('\n');
        }

        // only if there is return description, as we dont want empty @return tag
        if let Some(ret_desc) = ret_desc {
            ts_doc.push_str("@returns ");
            ts_doc.push_str(ret_desc);
        }
        ts_doc
    }
}

/// The first argument of a method: the pointer of the receiver.
enum Receiver {
    /// An expression reading the pointer off `this`, or `this` itself for
    /// `classless_this` functions.
    Expr(String),
    /// `self` is consumed, so the pointer is taken out of `this` first.
    Consumed,
}

/// What a function body is generated from besides its argument names.
struct BodyParams<'p> {
    receiver: Option<&'p Receiver>,
    ctor_is_subclass: bool,
    ctor_needs_sentinel_check: bool,
    consumes_self_subclass_guard: Option<&'p str>,
    method_class: Option<&'p str>,
    closure_invoke: bool,
    constructor: &'p Option<String>,
    adapter: &'p Adapter,
    instructions: &'p [InstructionData],
    debug_name: &'p str,
}

impl<'p> BodyParams<'p> {
    fn generate<'a, 'b>(
        &self,
        cx: &'a mut Context<'b>,
        arg_names: &[String],
        log_error: &mut bool,
    ) -> Result<JsBuilder<'a, 'b>, Error>
    where
        'p: 'a,
    {
        let mut js = JsBuilder::new(cx, self.debug_name);
        if self.ctor_is_subclass {
            js.prelude("super(__wbgSuperSkip);");
        }
        if self.ctor_needs_sentinel_check {
            js.prelude("if (arguments[0] === __wbgSuperSkip) return;");
        }
        if let Some(receiver) = self.receiver {
            if js.cx.generate_reinit {
                js.prelude(
                    "
                    if (this.__wbg_inst !== undefined && this.__wbg_inst !== __wbg_instance_id) {
                        throw new Error('Invalid stale object from previous Wasm instance');
                    }
                    ",
                );
            }
            if js.cx.config.debug {
                js.prelude(
                    "if (this.__wbg_ptr == 0) throw new Error('Attempt to use a moved value');",
                );
            }
            match receiver {
                Receiver::Expr(expr) => js.args.push(Value::Safe(expr.clone())),
                Receiver::Consumed => {
                    if let Some(guard) = self.consumes_self_subclass_guard {
                        js.prelude(guard);
                    }
                    js.begin_instr();
                    let ptr = js.declare("const", "ptr".into(), "this.__destroy_into_raw()".into());
                    if let Some(class) = self.method_class {
                        let free = js.class_free(class);
                        js.release(format!("if ({ptr}) {free}({ptr}, 1);"));
                    }
                    js.end_instr();
                    js.args.push(Value::Local(ptr));
                }
            }
        }
        // A closure's first two arguments are its state from the glue.
        let state = if self.closure_invoke { 2 } else { 0 };
        js.args
            .extend(arg_names.iter().enumerate().map(|(i, name)| {
                if i < state {
                    Value::Safe(name.clone())
                } else {
                    Value::Param(name.clone())
                }
            }));

        // Translate all instructions, the fun loop!
        //
        // This loop will process all instructions for this adapter function.
        // Each instruction will push/pop from the `js.stack` variable, and will
        // eventually build up the entire `js.prelude` variable with all the JS
        // code that we're going to be adding. Note that the stack at the end
        // represents all returned values.
        //
        // We don't actually manage a literal stack at runtime, but instead we
        // act as more of a compiler to generate straight-line code to make it
        // more JIT-friendly. The generated code should be equivalent to the
        // Wasm interface types stack machine, however.
        for instr in self.instructions {
            js.begin_instr();
            instruction(&mut js, &instr.instr, log_error, self.constructor)?;
            js.end_instr();
        }
        // An allocation made for a value returned to Wasm has no call to
        // take it, and only the allocating instruction's own tail can still
        // throw.
        if let Some(guard) = js.guard.take() {
            let (rest, _) = js.split_guard(&guard);
            let tail = guard.tail;
            js.close_guard(guard, rest, tail);
        }

        assert_eq!(
            js.stack.len(),
            self.adapter.results.len(),
            "stack size mismatch for {}",
            self.debug_name
        );
        match js.stack.len() {
            0 => {}
            1 => {
                let val = js.pop();
                js.prelude(&format!("return {val};"));
            }

            // TODO: this should be pretty trivial to support (commented out
            // code below), but we should be sure to have a test for this
            // somewhere. Currently I don't think it's possible to actually
            // exercise this with just Rust code, so let's wait until we get
            // some tests to enable this path.
            _ => bail!("multi-value returns from adapters not supported yet"),
            // _ => {
            //     let expr = js.stack.join(", ");
            //     js.stack.truncate(0);
            //     js.prelude(&format!("return [{}];", expr));
            // }
        }
        assert!(js.stack.is_empty());
        Ok(js)
    }
}

impl<'a, 'b> JsBuilder<'a, 'b> {
    pub fn new(cx: &'a mut Context<'b>, debug_name: &'a str) -> JsBuilder<'a, 'b> {
        cx.body_refs.clear();
        JsBuilder {
            cx,
            debug_name,
            args: Vec::new(),
            locals: HashSet::new(),
            tmp: 0,
            pre_try: String::new(),
            finally: String::new(),
            instr: InstrState::default(),
            guard: None,
            prelude: Vec::new(),
            stack: Vec::new(),
        }
    }

    pub fn arg(&self, idx: u32) -> &str {
        self.args[idx as usize].expr()
    }

    fn begin_instr(&mut self) {
        self.instr = InstrState {
            start: self.prelude.len(),
            ..InstrState::default()
        };
    }

    /// Tags the instruction's statements.
    fn end_instr(&mut self) {
        let InstrState {
            start,
            reads_local,
            effects,
            allocated_at,
            ..
        } = self.instr;
        if reads_local || effects {
            for stmt in &mut self.prelude[start..] {
                stmt.pure = false;
            }
        }
        if let (Some(at), Some(guard)) = (allocated_at, &mut self.guard) {
            guard.tail |= self.prelude.len() > at;
        }
    }

    /// Records `name` as bound in the function body and returns it.
    fn local(&mut self, name: String) -> String {
        self.instr.binds_local = true;
        self.locals.insert(name.clone());
        name
    }

    fn stmt(&mut self, kind: StmtKind) {
        self.prelude.push(Stmt { pure: true, kind });
    }

    /// Binds `name` to `expr`, declared with `keyword`.
    fn declare(&mut self, keyword: &'static str, name: String, expr: String) -> String {
        self.stmt(StmtKind::Decl {
            keyword: Some(keyword),
            name: name.clone(),
            expr,
        });
        self.local(name)
    }

    /// Whether an argument named `name` would shadow an identifier the body
    /// binds or references.
    fn shadows(&self, name: &str) -> bool {
        self.locals.contains(name)
            || self.cx.body_refs.contains(name)
            || BODY_GLOBALS.contains(&name)
    }

    /// Every identifier the body binds or references, for picking argument
    /// names that shadow none of them.
    fn scope(&self) -> IdentScope {
        let mut scope = IdentScope::default();
        for name in self.locals.iter().chain(self.cx.body_refs.iter()) {
            scope.reserve(name);
        }
        for name in BODY_GLOBALS {
            scope.reserve(name);
        }
        scope
    }

    pub fn prelude(&mut self, prelude: &str) {
        let mut text = String::new();
        for line in prelude.trim().lines().map(|l| l.trim()) {
            if !line.is_empty() {
                text.push_str(line);
                text.push('\n');
            }
        }
        if !text.is_empty() {
            self.stmt(StmtKind::Raw(text));
        }
    }

    pub fn finally(&mut self, finally: &str) {
        self.instr.effects = true;
        for line in finally.trim().lines().map(|l| l.trim()) {
            if !line.is_empty() {
                self.finally.push_str(line);
                self.finally.push('\n');
            }
        }
    }

    /// Registers `stmt` to release what the current instruction allocated
    /// for an argument. Called as soon as the allocation is made: whatever
    /// the instruction emits after it may throw and is guarded.
    fn release(&mut self, stmt: String) {
        self.instr.effects = true;
        let (start, len) = (self.instr.start, self.prelude.len());
        self.instr.allocated_at = Some(len);
        self.guard
            .get_or_insert_with(|| ArgGuard {
                start,
                first: len - start,
                tail: false,
                releases: Vec::new(),
            })
            .releases
            .push(stmt);
    }

    fn push_safe(&mut self, arg: String) {
        self.stack.push(Value::Safe(arg));
    }

    fn push_alloc(&mut self, arg: String) {
        self.stack.push(Value::Alloc(arg));
    }

    /// Renders the arguments of the call into Wasm, whose parameter types are
    /// `params` when it's a core function.
    ///
    /// When the arguments allocated, a throw before the call leaks what they
    /// allocated. So everything that depends only on the JS arguments runs
    /// ahead of the first allocation: the statements that read them, then the
    /// conversions Wasm applies to them (`+x`, `BigInt.asIntN(64, x)`), so a
    /// number passed for an `i64` throws before anything is allocated. When
    /// what remains can still throw after the first allocation, it is
    /// wrapped in a `try` whose `catch` releases the allocations, and the call
    /// follows it.
    ///
    /// An argument that allocates in the call itself, with nothing allocated
    /// before it, needs no `try`: the conversions alone run ahead of the call.
    fn take_args(&mut self, values: Vec<Value>, params: Option<&[ValType]>) -> Vec<String> {
        let guard = self.guard.take();
        let allocs = values.iter().any(|v| matches!(v, Value::Alloc(_)));
        let Some(params) = params.filter(|_| guard.is_some() || allocs) else {
            return values.into_iter().map(Value::into_expr).collect();
        };
        let (mut rest, mut guarded) = match &guard {
            Some(guard) => self.split_guard(guard),
            None => (Vec::new(), false),
        };
        let mut args = Vec::with_capacity(values.len());
        for (value, ty) in values.into_iter().zip(params) {
            let (expr, pure) = match value {
                Value::Local(expr) | Value::Safe(expr) | Value::Alloc(expr) => {
                    args.push(expr);
                    continue;
                }
                Value::Param(expr) => match ty {
                    ValType::I32 | ValType::F32 | ValType::F64 | ValType::I64 => (expr, true),
                    _ => {
                        args.push(expr);
                        continue;
                    }
                },
                Value::Expr { expr, pure } => (format!("({expr})"), pure),
            };
            // The conversion Wasm applies, which throws on the same values
            // with the same errors: `ToNumber` before `ToInt32` or rounding,
            // and `ToBigInt` before wrapping.
            let coerced = match ty {
                ValType::I32 | ValType::F32 | ValType::F64 => format!("+{expr}"),
                ValType::I64 => format!("BigInt.asIntN(64, {expr})"),
                _ => expr,
            };
            let i = self.tmp();
            let name = self.local(format!("val{i}"));
            let decl = Stmt {
                pure,
                kind: StmtKind::Decl {
                    keyword: Some("const"),
                    name: name.clone(),
                    expr: coerced,
                },
            };
            if pure || guard.is_none() {
                self.prelude.push(decl);
            } else {
                rest.push(decl);
                guarded = true;
            }
            args.push(name);
        }
        if let Some(guard) = guard {
            self.close_guard(guard, rest, guarded);
        }
        args
    }

    /// Moves the pure statements since the first allocation ahead of it,
    /// returning the rest and whether anything after the allocation is left
    /// to throw.
    fn split_guard(&mut self, guard: &ArgGuard) -> (Vec<Stmt>, bool) {
        let (pure, rest): (Vec<_>, Vec<_>) = self
            .prelude
            .split_off(guard.start)
            .into_iter()
            .partition(|stmt| stmt.pure);
        self.prelude.extend(pure);
        let guarded = rest.len() > guard.first;
        (rest, guarded)
    }

    /// Emits `rest`, wrapped in the `try` that releases the allocations when
    /// `guarded`.
    fn close_guard(&mut self, guard: ArgGuard, mut rest: Vec<Stmt>, guarded: bool) {
        if !guarded {
            self.prelude.extend(rest);
            return;
        }
        // What follows the `try` reads what it binds, so the bindings are
        // lifted into a `let`, taking literal initializers along.
        let mut names = Vec::new();
        rest.retain_mut(|stmt| {
            let StmtKind::Decl {
                keyword,
                name,
                expr,
                ..
            } = &mut stmt.kind
            else {
                return true;
            };
            if keyword.take().is_none() {
                return true;
            }
            let literal = expr.bytes().all(|b| b.is_ascii_digit());
            names.push(if literal {
                format!("{name} = {expr}")
            } else {
                name.clone()
            });
            !literal
        });
        let mut open = String::new();
        if !names.is_empty() {
            writeln!(open, "let {};", names.join(", ")).unwrap();
        }
        open.push_str("try {\n");
        let mut close = String::from("} catch (e) {\n");
        for release in guard.releases.iter().rev() {
            close.push_str(release);
            close.push('\n');
        }
        close.push_str("throw e;\n}\n");
        self.stmt(StmtKind::Raw(open));
        self.prelude.extend(rest);
        self.stmt(StmtKind::Raw(close));
    }

    pub fn tmp(&mut self) -> usize {
        let ret = self.tmp;
        self.tmp += 1;
        ret
    }

    fn pop_value(&mut self) -> Value {
        match self.stack.pop() {
            Some(value) => value,
            None => panic!("popping an empty stack in {}", self.debug_name),
        }
    }

    fn pop(&mut self) -> String {
        let value = self.pop_value();
        if matches!(value, Value::Local(_) | Value::Expr { pure: false, .. }) {
            self.instr.reads_local = true;
        }
        value.into_expr()
    }

    /// Pushes `arg`; an argument or local pushed back unchanged stays one.
    fn push(&mut self, arg: String) {
        let value = if let Some(value) = self.args.iter().find(|a| a.expr() == arg) {
            value.clone()
        } else if self.locals.contains(&arg) {
            Value::Local(arg)
        } else {
            Value::Expr {
                expr: arg,
                pure: !(self.instr.reads_local || self.instr.binds_local),
            }
        };
        self.stack.push(value);
    }

    fn class_free(&mut self, class: &str) -> String {
        let resolved = self.cx.resolve_class_name(class).to_string();
        self.cx
            .wasm_export_ref(&wasm_bindgen_shared::free_function(&resolved))
    }

    fn assert_class(&mut self, arg: &str, class: &str) {
        self.cx.expose_assert_class();
        let identifier = self.cx.require_class_reference(class);
        self.prelude(&format!("_assertClass({arg}, {identifier});"));
    }

    /// `assert_class` for boundaries that take the receiver by value
    /// (ownership transfer to Rust). For classes participating in an
    /// `extends` chain, additionally reject Rust descendant instances: a
    /// descendant's `__wbg_ptr` is its own (descendant) pointer, which
    /// is incompatible with this class's wasm shim, so
    /// `__destroy_into_raw()` would hand the wrong pointer to Rust —
    /// type-confused free / UB. The check compares `arg.__wbg_ptr`
    /// against `arg.__wbg_ptr_<Class>`: for the actual class instance
    /// (or a user-written JS-only subclass) those agree; for a Rust
    /// descendant the per-class slot holds the upcasted ancestor pointer
    /// and differs from `__wbg_ptr`, so we throw.
    fn assert_owned_class(&mut self, arg: &str, class: &str) {
        self.assert_class(arg, class);
        let resolved = self.cx.resolve_class_name(class).to_string();
        let participates = self
            .cx
            .exported_classes
            .get(&resolved)
            .is_some_and(|c| c.participates_in_inheritance);
        if participates {
            let identifier = self.cx.require_class_identifier(class);
            self.prelude(&format!(
                "if ({arg}.__wbg_ptr !== {arg}.__wbg_ptr_{identifier}) {{ \
                    throw new TypeError('expected exact instance of {identifier}; \
                    a wasm-bindgen descendant cannot be consumed by-value as its ancestor'); \
                }}"
            ));
        }
    }

    fn assert_number(&mut self, arg: &str) {
        if !self.cx.config.debug {
            return;
        }
        self.cx.expose_assert_num();
        self.prelude(&format!("_assertNum({arg});"));
    }

    fn assert_bigint(&mut self, arg: &str) {
        if !self.cx.config.debug {
            return;
        }
        self.cx.expose_assert_bigint();
        self.prelude(&format!("_assertBigInt({arg});"));
    }

    fn assert_bool(&mut self, arg: &str) {
        if !self.cx.config.debug {
            return;
        }
        self.cx.expose_assert_bool();
        self.prelude(&format!("_assertBoolean({arg});"));
    }

    /// The test for an incoming option holding no value: only `undefined`
    /// when `Strict`, only `null` for a plain `Nullable`, otherwise either.
    fn is_none(&mut self, val: &str, kind: OptionKind) -> String {
        match kind {
            OptionKind::Strict => format!("{val} === undefined"),
            OptionKind::Nullable => format!("{val} === null"),
            OptionKind::Lenient | OptionKind::OptionNullable => {
                self.cx.expose_is_like_none();
                format!("isLikeNone({val})")
            }
        }
    }

    fn is_some(&mut self, val: &str, kind: OptionKind) -> String {
        match kind {
            OptionKind::Strict => format!("{val} !== undefined"),
            OptionKind::Nullable => format!("{val} !== null"),
            OptionKind::Lenient | OptionKind::OptionNullable => {
                self.cx.expose_is_like_none();
                format!("!isLikeNone({val})")
            }
        }
    }

    /// `value` when `val` holds one, else the ABI word of the empty state it
    /// is: `undefined_abi` for `undefined` (and for `null` when lenient),
    /// and when nullable `null_abi` for `null`.
    fn option_abi(
        &mut self,
        val: &str,
        kind: OptionKind,
        undefined_abi: &str,
        null_abi: &str,
        value: &str,
    ) -> String {
        match kind {
            OptionKind::OptionNullable => format!(
                "{val} === undefined ? {undefined_abi} : {val} === null ? {null_abi} : {value}"
            ),
            OptionKind::Nullable => format!("{val} === null ? {null_abi} : {value}"),
            kind => {
                let none = self.is_none(val, kind);
                format!("{none} ? {undefined_abi} : {value}")
            }
        }
    }

    /// The tag word of a native option: whether `val` holds a value, or when
    /// nullable `0` for `undefined`, `2` for `null` and `1` for a value.
    fn option_tag(&mut self, val: &str, kind: OptionKind) -> String {
        if kind.nullable() {
            self.option_abi(val, kind, "0", "2", "1")
        } else {
            self.is_some(val, kind)
        }
    }

    /// The length word of an incoming slice just passed to wasm. A nullable
    /// one must tell its empty states apart: `0` for `undefined`, the `null`
    /// handle for `null`.
    fn vector_len(&mut self, val: &str, kind: OptionKind) -> String {
        if kind.nullable() {
            self.option_abi(val, kind, "0", &NULL_HANDLE.to_string(), "WASM_VECTOR_LEN")
        } else {
            "WASM_VECTOR_LEN".to_string()
        }
    }

    fn assert_optional_number(&mut self, arg: &str, kind: OptionKind) {
        if !self.cx.config.debug {
            return;
        }
        let some = self.is_some(arg, kind);
        self.prelude(&format!("if ({some}) {{"));
        self.assert_number(arg);
        self.prelude("}");
    }

    fn assert_non_null(&mut self, arg: &str) {
        self.cx.expose_assert_non_null();
        self.prelude(&format!("_assertNonNull({arg});"));
    }

    fn assert_char(&mut self, arg: &str) {
        self.cx.expose_assert_char();
        self.prelude(&format!("_assertChar({arg});"));
    }

    fn assert_optional_bigint(&mut self, arg: &str, kind: OptionKind) {
        if !self.cx.config.debug {
            return;
        }
        let some = self.is_some(arg, kind);
        self.prelude(&format!("if ({some}) {{"));
        self.assert_bigint(arg);
        self.prelude("}");
    }

    fn assert_optional_bool(&mut self, arg: &str, kind: OptionKind) {
        if !self.cx.config.debug {
            return;
        }
        let some = self.is_some(arg, kind);
        self.prelude(&format!("if ({some}) {{"));
        self.assert_bool(arg);
        self.prelude("}");
    }

    /// Values that are not objects with a numeric `length`, such as an
    /// `ArrayBuffer` or a string, would otherwise be copied into Wasm as an
    /// empty or zeroed vector.
    fn assert_array_like(&mut self, arg: &str, kind: &VectorKind) {
        if !self.cx.config.debug {
            return;
        }
        self.cx.expose_assert_array_like();
        match kind {
            VectorKind::Externref | VectorKind::NamedExternref(_) => {
                self.prelude(&format!("_assertArrayLike({arg});"));
            }
            _ => {
                let typed_array = kind.js_ty();
                self.prelude(&format!("_assertArrayLike({arg}, '{typed_array}');"));
            }
        }
    }

    fn assert_optional_array_like(
        &mut self,
        arg: &str,
        kind: &VectorKind,
        option_kind: OptionKind,
    ) {
        if !self.cx.config.debug {
            return;
        }
        let some = self.is_some(arg, option_kind);
        self.prelude(&format!("if ({some}) {{"));
        self.assert_array_like(arg, kind);
        self.prelude("}");
    }

    /// Mutable slices are copied back into the buffer of the original typed
    /// array as raw bytes, so it needs the same element size and the same
    /// integer or float kind.
    fn assert_typed_array(&mut self, arg: &str, kind: &VectorKind) {
        if !self.cx.config.debug {
            return;
        }
        self.cx.expose_assert_typed_array();
        let typed_array = kind.js_ty();
        let size = kind.size();
        self.prelude(&format!(
            "_assertTypedArray({arg}, '{typed_array}', {size});"
        ));
    }

    fn assert_not_moved(&mut self, arg: &str) {
        if self.cx.generate_reinit {
            // Under reset state, we need comprehensive validation
            self.prelude(&format!(
                "\
                if (({arg}).__wbg_inst !== undefined && ({arg}).__wbg_inst !== __wbg_instance_id) {{
                    throw new Error('Invalid stale object from previous Wasm instance');
                }}
                "
            ));
        }
        if self.cx.config.debug {
            // Debug mode only checks for moved values
            self.prelude(&format!(
                "\
                if ({arg}.__wbg_ptr === 0) {{
                    throw new Error('Attempt to use a moved value');
                }}
                ",
            ));
        }
    }

    fn string_to_memory(
        &mut self,
        mem: walrus::MemoryId,
        malloc: walrus::FunctionId,
        free: walrus::FunctionId,
        realloc: Option<walrus::FunctionId>,
    ) {
        let pass = self.cx.expose_pass_string_to_wasm(mem);
        let val = self.pop();
        let malloc = self.cx.export_name_of(malloc);
        let i = self.tmp();
        let malloc = self.cx.wasm_export_ref(&malloc);
        let realloc = self.cx.optional_func_arg(realloc);
        let ptr = self.declare(
            "const",
            format!("ptr{i}"),
            format!("{pass}({val}, {malloc}{realloc})"),
        );
        let len = self.declare("const", format!("len{i}"), "WASM_VECTOR_LEN".into());
        let release = self.vector_release(&VectorKind::String, mem, free, &ptr, &len);
        self.release(release);
        self.push(ptr);
        self.push(len);
    }

    /// Releases a vector JS allocated at `ptr`, unless it's absent.
    fn vector_release(
        &mut self,
        kind: &VectorKind,
        mem: walrus::MemoryId,
        free: walrus::FunctionId,
        ptr: &str,
        len: &str,
    ) -> String {
        let free = self.cx.wasm_export_of(free);
        let size = kind.size();
        let elems = match kind {
            VectorKind::Externref | VectorKind::NamedExternref(_) => {
                match (
                    self.cx.aux.externref_table,
                    self.cx.aux.externref_drop_slice,
                ) {
                    (Some(_), Some(drop)) => {
                        let drop = self.cx.wasm_export_of(drop);
                        format!("{drop}({ptr}, {len}); ")
                    }
                    _ => {
                        self.cx.expose_drop_ref();
                        let view = self.cx.expose_dataview_memory(mem);
                        let view = if self.cx.config.mode.emscripten() {
                            view.name.to_string()
                        } else {
                            format!("{view}()")
                        };
                        format!(
                            "for (let i = 0; i < {len}; i++) dropObject({view}.getUint32({ptr} + 4 * i, true)); "
                        )
                    }
                }
            }
            _ => String::new(),
        };
        format!("if ({ptr}) {{ {elems}{free}({ptr}, {len} * {size}, {size}); }}")
    }
}

/// `value` unless `val` is an ABI empty state: `undefined` for
/// `undefined_abi` and, when `kind` is nullable, `null` for `null_abi`. A
/// plain `Nullable` has no `undefined` state.
fn abi_option(
    val: &str,
    kind: OptionKind,
    undefined_abi: &str,
    null_abi: &str,
    value: &str,
) -> String {
    match kind {
        OptionKind::OptionNullable => {
            format!("{val} === {undefined_abi} ? undefined : {val} === {null_abi} ? null : {value}")
        }
        OptionKind::Nullable => format!("{val} === {null_abi} ? null : {value}"),
        OptionKind::Lenient | OptionKind::Strict => {
            format!("{val} === {undefined_abi} ? undefined : {value}")
        }
    }
}

/// The empty value of an outgoing optional slice whose pointer is null: when
/// `kind` is nullable, `null` for a length of the `null` handle.
fn empty_vector_value(len: &str, kind: OptionKind) -> String {
    match kind {
        OptionKind::OptionNullable => format!("({len} === {NULL_HANDLE} ? null : undefined)"),
        OptionKind::Nullable => "null".to_string(),
        OptionKind::Lenient | OptionKind::Strict => "undefined".to_string(),
    }
}

/// The initialiser of an outgoing optional slice's result, which is
/// `undefined` by default.
fn empty_vector_init(len: &str, kind: OptionKind) -> String {
    if kind.nullable() {
        format!(" = {}", empty_vector_value(len, kind))
    } else {
        String::new()
    }
}

fn instruction(
    js: &mut JsBuilder,
    instr: &Instruction,
    log_error: &mut bool,
    constructor: &Option<String>,
) -> Result<(), Error> {
    fn wasm_to_string_enum(name: &str, index: &str) -> String {
        // e.g. ["a","b","c"][someIndex]
        format!("__wbindgen_enum_{name}[{index}]")
    }
    fn string_enum_to_wasm(name: &str, invalid: u32, enum_val: &str) -> String {
        // e.g. (["a","b","c"].indexOf(someEnumVal) + 1 || 4) - 1
        //                                                 |
        //                                           invalid + 1
        //
        // The idea is that `indexOf` returns -1 if someEnumVal is invalid,
        // and with +1 we get 0 which is falsey, so we can use || to
        // substitute invalid+1. Finally, we just do -1 to get the correct
        // values for everything.
        format!(
            "(__wbindgen_enum_{name}.indexOf({enum_val}) + 1 || {invalid}) - 1",
            invalid = invalid + 1
        )
    }

    fn int128_to_int64x2(val: &str) -> (String, String) {
        // we don't need to perform any conversion here, because the JS
        // WebAssembly API will automatically convert the bigints to 64 bits
        // for us. This even allows us to ignore signedness.
        let low = val.to_owned();
        let high = format!("{val} >> BigInt(64)");
        (low, high)
    }
    fn int64x2_to_int128(low: String, high: String, signed: bool) -> String {
        let low = format!("BigInt.asUintN(64, {low})");
        if signed {
            format!("({low} | ({high} << BigInt(64)))")
        } else {
            format!("({low} | (BigInt.asUintN(64, {high}) << BigInt(64)))")
        }
    }

    match instr {
        Instruction::ArgGet(n) => {
            let arg = js.args[*n as usize].clone();
            js.stack.push(arg);
        }

        Instruction::CallExport(_)
        | Instruction::CallAdapter(_)
        | Instruction::DeferFree { .. } => {
            let is_export_call = matches!(
                instr,
                Instruction::CallExport(_) | Instruction::DeferFree { .. }
            );
            let mut guard = if js.cx.aux.wrapped_js_tag.is_some() && is_export_call {
                ExportGuard::Abort
            } else if js.cx.generate_reinit && is_export_call {
                ExportGuard::GuardOnly
            } else {
                ExportGuard::None
            };
            let invoc = Invocation::from(instr, js.cx.module);
            let (mut params, results) = invoc.params_results(js.cx);

            let mut args = Vec::new();
            let tmp = js.tmp();
            if invoc.defer() {
                if let Instruction::DeferFree { .. } = instr {
                    // Ignore `free`'s final `align` argument, since that's manually inserted later.
                    params -= 1;
                }
                // If the call is deferred, the arguments to the function still need to be
                // accessible in the `finally` block, so we declare variables to hold the args
                // outside of the try-finally block and then set those to the args.
                for i in 0..params {
                    let arg = &js.stack[js.stack.len() - params + i];
                    let name = format!("deferred{tmp}_{i}");
                    writeln!(js.pre_try, "let {name};").unwrap();
                    js.prelude(&format!("{name} = {arg};"));
                    args.push(js.local(name));
                }
                if let Instruction::DeferFree { align, .. } = instr {
                    // add alignment
                    args.push(align.to_string());
                }
            } else {
                // Otherwise, pop off the number of parameters for the function we're calling.
                let mut values = Vec::with_capacity(params);
                for _ in 0..params {
                    values.push(js.pop_value());
                }
                values.reverse();
                let core_params = match invoc {
                    Invocation::Core { id, .. } => {
                        let ty = js.cx.module.funcs.get(id).ty();
                        Some(js.cx.module.types.get(ty).params().to_vec())
                    }
                    _ => None,
                };
                args = js.take_args(values, core_params.as_deref());
            }

            // Call the function through an export of the underlying module.
            let mut comments = String::new();
            let call = invoc.invoke(js.cx, &args, &mut comments, log_error, &mut guard)?;
            js.prelude(&comments);

            // And then figure out how to actually handle where the call
            // happens. This is pretty conditional depending on the number of
            // return values of the function.
            match (invoc.defer(), results) {
                (true, 0) => {
                    js.finally(&maybe_wrap_export_call(&call, guard));
                }
                (true, _) => panic!("deferred calls must have no results"),
                (false, 0) if js.cx.current_adapter_suspending => {
                    // A `#[wasm_bindgen(suspending)]` import must return the
                    // Promise to `WebAssembly.Suspending` even when the Rust
                    // return type is `()`.  Without `return` the fiber never
                    // suspends and block_on_promise returns immediately with null.
                    // Emit `return` directly into prelude; don't push to the
                    // adapter stack (which must stay at len=0 for void).
                    js.prelude(&format!("return {call};"));
                }
                (false, 0) if js.cx.current_adapter_jspi => {
                    // Void JSPI export: `await` the Promise from the promising
                    // call so that deferred frees in the `finally` block run
                    // only after the fiber has completed.
                    js.prelude(&maybe_wrap_export_call(&format!("await {call}"), guard));
                }
                (false, 0) => js.prelude(&maybe_wrap_export_call(&call, guard)),
                (false, n) => {
                    // For JSPI exports the `call` expression returns a Promise;
                    // `await` it so the resolved WASM return value
                    // is available for post-processing.  The outer JS
                    // wrapper function is marked `async` (via the `jspi_async` flag
                    // on `JsFunction`) so that `await` is legal here.
                    let maybe_await = if js.cx.current_adapter_jspi {
                        "await "
                    } else {
                        ""
                    };
                    let body = if matches!(guard, ExportGuard::None) {
                        format!("const ret = {maybe_await}{call};")
                    } else {
                        format!(
                            "let ret;\n{}",
                            maybe_wrap_export_call(&format!("ret = {maybe_await}{call}"), guard)
                        )
                    };
                    js.prelude(&body);
                    let ret = js.local("ret".to_string());
                    if n == 1 {
                        js.push(ret);
                    } else {
                        for i in 0..n {
                            js.push(format!("{ret}[{i}]"));
                        }
                    }
                }
            }
        }

        Instruction::Int32ToWasm => {
            let val = js.pop();
            js.assert_number(&val);
            js.push(val);
        }
        Instruction::WasmToInt32 { unsigned_32 } => {
            let val = js.pop();
            if *unsigned_32 {
                // When converting to a JS number we need to specially handle the `u32`
                // case because if the high bit is set then it comes out as a negative
                // number, but we want to switch that to an unsigned representation.
                js.push(format!("{val} >>> 0"))
            } else {
                js.push(val)
            }
        }

        Instruction::Int64ToWasm => {
            let val = js.pop();
            js.assert_bigint(&val);
            js.push(val);
        }
        Instruction::WasmToInt64 { unsigned } => {
            let val = js.pop();
            if *unsigned {
                js.push(format!("BigInt.asUintN(64, {val})"))
            } else {
                js.push(val)
            }
        }

        Instruction::Int128ToWasm => {
            let val = js.pop();
            js.assert_bigint(&val);
            let (low, high) = int128_to_int64x2(&val);
            js.push(low);
            js.push(high);
        }
        Instruction::WasmToInt128 { signed } => {
            let high = js.pop();
            let low = js.pop();
            js.push(int64x2_to_int128(low, high, *signed));
        }

        Instruction::OptionInt128ToWasm { kind } => {
            let val = js.pop();
            js.assert_optional_bigint(&val, *kind);
            let (low, high) = int128_to_int64x2(&val);
            let none = js.is_none(&val, *kind);
            let tag = js.option_tag(&val, *kind);
            js.push(tag);
            js.push(format!("{none} ? BigInt(0) : {low}"));
            js.push(format!("{none} ? BigInt(0) : {high}"));
        }
        Instruction::OptionWasmToInt128 { signed, kind } => {
            let high = js.pop();
            let low = js.pop();
            let present = js.pop();
            let val = int64x2_to_int128(low, high, *signed);
            js.push(abi_option(&present, *kind, "0", "2", &val));
        }

        Instruction::WasmToStringEnum { name } => {
            let index = js.pop();
            js.cx.expose_string_enum(name);
            js.push(wasm_to_string_enum(name, &index))
        }

        Instruction::OptionWasmToStringEnum { name, hole, kind } => {
            // Since hole is currently variant_count+1 and the lookup is
            // ["a","b","c"][index], the lookup will implicitly return map
            // the hole to undefined, because OOB indexes will return undefined.
            let index = js.pop();
            js.cx.expose_string_enum(name);
            let lookup = wasm_to_string_enum(name, &index);
            if kind.nullable() {
                js.push(format!("{index} === {} ? null : {lookup}", hole + 1))
            } else {
                js.push(lookup)
            }
        }

        Instruction::StringEnumToWasm { name, invalid } => {
            let enum_val = js.pop();
            js.cx.expose_string_enum(name);
            js.push_safe(string_enum_to_wasm(name, *invalid, &enum_val))
        }

        Instruction::OptionStringEnumToWasm {
            name,
            invalid,
            hole,
            kind,
        } => {
            let enum_val = js.pop();
            js.cx.expose_string_enum(name);
            let enum_val_expr = string_enum_to_wasm(name, *invalid, &enum_val);

            // e.g. isLikeNone(someEnumVal) ? 4 : (string_enum_to_wasm(someEnumVal))
            // A nullable `null` is the index above the hole.
            let abi = js.option_abi(
                &enum_val,
                *kind,
                &hole.to_string(),
                &(hole + 1).to_string(),
                &format!("({enum_val_expr})"),
            );
            js.push_safe(abi)
        }

        Instruction::MemoryToString(mem) => {
            let len = js.pop();
            let ptr = js.pop();
            let get = js.cx.expose_get_string_from_wasm(*mem);
            js.push(format!("{get}({ptr}, {len})"));
        }

        Instruction::StringToMemory {
            mem,
            malloc,
            free,
            realloc,
        } => {
            js.string_to_memory(*mem, *malloc, *free, *realloc);
        }

        Instruction::Retptr { size } => {
            js.cx.inject_stack_pointer_shim()?;
            let sp = js.cx.wasm_export_ref("__wbindgen_add_to_stack_pointer");
            let coerce = js.cx.coerce_ptr_suffix();
            let retptr = js.declare("const", "retptr".into(), format!("{sp}(-{size}){coerce}"));
            js.finally(&format!("{sp}({size});"));
            js.push(retptr);
        }

        Instruction::StoreRetptr { ty, offset, mem } => {
            let mem = js.cx.expose_dataview_memory(*mem);
            let (method, size) = match ty {
                AdapterType::I32 => ("setInt32", 4),
                AdapterType::I64 => ("setBigInt64", 8),
                AdapterType::F32 => ("setFloat32", 4),
                AdapterType::F64 => ("setFloat64", 8),
                other => bail!("invalid aggregate return type {other:?}"),
            };
            // Note that we always assume the return pointer is argument 0,
            // which is currently the case for LLVM. On wasm64 the retptr is
            // an LLVM-synthesized `i64` sret, arriving in JS as a BigInt, so
            // coerce it to a number before doing pointer arithmetic.
            let val = js.pop();
            let mem_string = mem.access(js.cx.config.mode.emscripten());
            let expr = format!(
                "{mem_string}.{method}({retptr} + {size} * {offset}, {val}, true);",
                retptr = if js.cx.memory64 {
                    format!("Number({})", js.arg(0))
                } else {
                    format!("({} >>> 0)", js.arg(0))
                },
            );
            js.prelude(&expr);
        }

        Instruction::LoadRetptr { ty, offset, mem } => {
            let mem = js.cx.expose_dataview_memory(*mem);
            let (method, quads) = match ty {
                AdapterType::I32 => ("getInt32", 1),
                AdapterType::I64 => ("getBigInt64", 2),
                AdapterType::F32 => ("getFloat32", 1),
                AdapterType::F64 => ("getFloat64", 2),
                other => bail!("invalid aggregate return type {other:?}"),
            };
            let size = quads * 4;
            // Separate the offset and the scaled offset, because otherwise you don't guarantee
            // that the variable names will be unique.
            let scaled_offset = offset / quads;
            // If we're loading from the return pointer then we must have pushed
            // it earlier, and we always push the same value, so load that value
            // here
            let mem_string = mem.access(js.cx.config.mode.emscripten());

            let expr = format!("{mem_string}.{method}(retptr + {size} * {scaled_offset}, true)");
            js.prelude(&format!("var r{offset} = {expr};"));
            let r = js.local(format!("r{offset}"));
            js.push(r);
        }

        Instruction::I32FromBool => {
            let val = js.pop();
            js.assert_bool(&val);
            // JS will already coerce booleans into numbers for us
            js.push(val);
        }

        Instruction::I32FromStringFirstChar => {
            let val = js.pop();
            let i = js.tmp();
            let val = js.declare("const", format!("char{i}"), format!("{val}.codePointAt(0)"));
            js.assert_char(&val);
            js.push(val);
        }

        Instruction::I32FromExternrefOwned => {
            js.cx.expose_add_heap_object();
            let val = js.pop();
            js.push_alloc(format!("addHeapObject({val})"));
        }

        Instruction::I32FromExternrefBorrow => {
            js.cx.expose_borrowed_objects();
            js.cx.expose_global_stack_pointer();
            let val = js.pop();
            // Pushed before the `try` whose `finally` pops, so a throw while
            // converting a later argument leaves the stack balanced.
            let i = js.tmp();
            writeln!(js.pre_try, "const borrow{i} = addBorrowedObject({val});").unwrap();
            let borrow = js.local(format!("borrow{i}"));
            js.push(borrow);
            js.finally("heap[stack_pointer++] = undefined;");
        }

        Instruction::I32FromExternrefRustOwned { class } => {
            let val = js.pop();
            js.assert_owned_class(&val, class);
            js.assert_not_moved(&val);
            let i = js.tmp();
            let ptr = js.declare(
                "var",
                format!("ptr{i}"),
                format!("{val}.__destroy_into_raw()"),
            );
            let free = js.class_free(class);
            js.release(format!("if ({ptr}) {free}({ptr}, 1);"));
            js.push(ptr);
        }

        Instruction::I32FromExternrefRustBorrow { class } => {
            let val = js.pop();
            js.assert_class(&val, class);
            js.assert_not_moved(&val);
            // For inheritance-participating classes, route through the
            // per-class pointer field. `_assertClass` uses `instanceof`,
            // so a subclass instance passes the check, but `{val}.__wbg_ptr`
            // would be the *descendant* pointer — handing that to this
            // class's wasm shim would type-confuse the borrow. The
            // per-class field `__wbg_ptr_<DefiningClass>` is populated by
            // the constructor / `__wrap` upcast chain on every instance,
            // including subclass instances, so it is the correct ancestor
            // pointer.
            let resolved = js.cx.resolve_class_name(class).to_string();
            let participates = js
                .cx
                .exported_classes
                .get(&resolved)
                .is_some_and(|c| c.participates_in_inheritance);
            // Read when Rust is called, after every by-value argument has
            // been taken from JS, so the same object passed twice reaches
            // Rust as null rather than both owned and borrowed.
            if participates {
                let identifier = js.cx.require_class_identifier(class);
                js.push_safe(format!("{val}.__wbg_ptr_{identifier}"));
            } else {
                js.push_safe(format!("{val}.__wbg_ptr"));
            }
        }

        Instruction::I32FromOptionRust { class, kind } => {
            let val = js.pop();
            let i = js.tmp();
            // `Nullable::Null` is the pointer `1`, which no instance can have.
            let (empty, owned) = if kind.nullable() {
                (format!("{val} === null ? 1 : 0"), "> 1")
            } else {
                ("0".into(), "")
            };
            let ptr = js.declare("let", format!("ptr{i}"), empty);
            let some = js.is_some(&val, *kind);
            js.prelude(&format!("if ({some}) {{"));
            js.assert_owned_class(&val, class);
            js.assert_not_moved(&val);
            js.prelude(&format!("{ptr} = {val}.__destroy_into_raw();"));
            js.prelude("}");
            let free = js.class_free(class);
            js.release(format!("if ({ptr}{owned}) {free}({ptr}, 1);"));
            js.push(ptr);
        }

        Instruction::I32FromOptionExternref {
            table_and_alloc,
            kind,
        } => {
            let val = js.pop();
            let alloc = match table_and_alloc {
                Some((table, alloc)) => js
                    .cx
                    .expose_add_to_externref_table(*table, *alloc)
                    .to_string(),
                None => {
                    js.cx.expose_add_heap_object();
                    "addHeapObject".to_string()
                }
            };
            // A nullable `null` is the fixed handle, which Rust reads as
            // `Null` without owning a slot.
            let abi = js.option_abi(
                &val,
                *kind,
                "0",
                &NULL_HANDLE.to_string(),
                &format!("{alloc}({val})"),
            );
            js.push_alloc(abi);
        }

        Instruction::I32FromOptionU32Sentinel { kind } => {
            let val = js.pop();
            js.assert_optional_number(&val, *kind);
            let abi = js.option_abi(&val, *kind, U32_OPTION_SENTINEL, U32_NULL_SENTINEL, &val);
            js.push(abi);
        }

        Instruction::I32FromOptionBool { kind } => {
            let val = js.pop();
            js.assert_optional_bool(&val, *kind);
            let abi = js.option_abi(
                &val,
                *kind,
                U32_OPTION_SENTINEL,
                U32_NULL_SENTINEL,
                &format!("{val} ? 1 : 0"),
            );
            js.push_safe(abi);
        }

        Instruction::I32FromOptionChar { kind } => {
            let val = js.pop();
            let i = js.tmp();
            let abi = js.option_abi(
                &val,
                *kind,
                U32_OPTION_SENTINEL,
                U32_NULL_SENTINEL,
                &format!("{val}.codePointAt(0)"),
            );
            let val = js.declare("const", format!("char{i}"), abi);
            js.cx.expose_assert_char();
            let mut value = Vec::new();
            if kind.accepts_undefined() {
                value.push(format!("{val} !== {U32_OPTION_SENTINEL}"));
            }
            if kind.nullable() {
                value.push(format!("{val} !== {U32_NULL_SENTINEL}"));
            }
            let value = value.join(" && ");
            js.prelude(&format!("if ({value}) {{ _assertChar({val}); }}"));
            js.push(val);
        }

        Instruction::F64FromEnum => {
            let val = js.pop();
            js.assert_number(&val);
            js.push(val);
        }

        Instruction::F64FromOptionEnum { hole, kind } => {
            let val = js.pop();
            js.assert_optional_number(&val, *kind);
            let abi = js.option_abi(&val, *kind, &hole.to_string(), F64_NULL_SENTINEL, &val);
            js.push(abi);
        }

        Instruction::F64FromOptionSentinelInt { signed, kind } => {
            let val = js.pop();
            js.assert_optional_number(&val, *kind);

            // We need to convert the given number to a 32-bit integer before
            // passing it to the ABI for 2 reasons:
            // 1. Rust's behavior for `value_f64 as i32/u32` is different from
            //    the WebAssembly behavior for values outside the 32-bit range.
            //    We could implement this behavior in Rust too, but it's easier
            //    to do it in JS.
            // 2. If we allowed values outside the 32-bit range, the sentinel
            //    value itself would be allowed. This would make it impossible
            //    to distinguish between the sentinel value and a valid value.
            //
            // To perform the actual conversion, we use JS bit shifts. Handily,
            // >> and >>> perform a conversion to i32 and u32 respectively
            // to apply the bit shift, so we can use e.g. x >>> 0 to convert to
            // u32.

            let op = if *signed { ">>" } else { ">>>" };
            let abi = js.option_abi(
                &val,
                *kind,
                F64_OPTION_SENTINEL,
                F64_NULL_SENTINEL,
                &format!("({val}) {op} 0"),
            );
            js.push(abi);
        }
        Instruction::F64FromOptionSentinelNumber { kind } => {
            // Used when the underlying integer spans the full f64-safe range
            // (e.g. i64/u64 on wasm64). No narrowing; just coerce to number.
            let val = js.pop();
            js.assert_optional_number(&val, *kind);
            let abi = js.option_abi(
                &val,
                *kind,
                F64_OPTION_SENTINEL,
                F64_NULL_SENTINEL,
                &format!("Number({val})"),
            );
            js.push(abi);
        }
        Instruction::F64FromOptionSentinelF32 { kind } => {
            let val = js.pop();
            js.assert_optional_number(&val, *kind);

            // Similar to the above 32-bit integer variant, we convert the
            // number to a 32-bit *float* before passing it to the ABI. This
            // ensures consistent behavior with WebAssembly and makes it
            // possible to use a sentinel value.

            let abi = js.option_abi(
                &val,
                *kind,
                F64_OPTION_SENTINEL,
                F64_NULL_SENTINEL,
                &format!("Math.fround({val})"),
            );
            js.push(abi);
        }

        Instruction::FromOptionNative { ty, kind } => {
            let val = js.pop();
            if *ty == ValType::I64 {
                js.assert_optional_bigint(&val, *kind);
            } else {
                js.assert_optional_number(&val, *kind);
            }
            let none = js.is_none(&val, *kind);
            let tag = js.option_tag(&val, *kind);
            js.push_safe(tag);
            js.push(format!(
                "{none} ? {zero} : {val}",
                zero = if *ty == ValType::I64 {
                    // We can't use bigint literals for now. See:
                    // https://github.com/wasm-bindgen/wasm-bindgen/issues/4246
                    "BigInt(0)"
                } else {
                    "0"
                }
            ));
        }

        Instruction::VectorToMemory {
            kind,
            malloc,
            free,
            mem,
        } => {
            let val = js.pop();
            js.assert_array_like(&val, kind);
            let func = js.cx.pass_to_wasm_function(kind.clone(), *mem);
            let malloc = js.cx.wasm_export_of(*malloc);
            let i = js.tmp();
            let ptr = js.declare(
                "const",
                format!("ptr{i}"),
                format!("{func}({val}, {malloc})"),
            );
            let len = js.declare("const", format!("len{i}"), "WASM_VECTOR_LEN".into());
            let release = js.vector_release(kind, *mem, *free, &ptr, &len);
            js.release(release);
            js.push(ptr);
            js.push(len);
        }

        Instruction::UnwrapResult { table_and_drop } => {
            let take_object = if let Some((table, drop)) = *table_and_drop {
                js.cx
                    .expose_take_from_externref_table(table, drop)
                    .to_string()
            } else {
                js.cx.expose_take_object();
                "takeObject".to_string()
            };
            // is_err is popped first. The original layout was: ResultAbi {
            //    abi: ResultAbiUnion<T>,
            //    err: u32,
            //    is_err: u32,
            // }
            // So is_err is last to be added to the stack.
            let is_err = js.pop();
            let err = js.pop();
            js.prelude(&format!(
                "
                if ({is_err}) {{
                    throw {take_object}({err});
                }}
                ",
            ));
        }

        Instruction::UnwrapResultString { table_and_drop } => {
            let take_object = if let Some((table, drop)) = *table_and_drop {
                js.cx
                    .expose_take_from_externref_table(table, drop)
                    .to_string()
            } else {
                js.cx.expose_take_object();
                "takeObject".to_string()
            };
            let is_err = js.pop();
            let err = js.pop();
            let len = js.pop();
            let ptr = js.pop();
            let i = js.tmp();
            js.prelude(&format!(
                "
                var ptr{i} = {ptr};
                var len{i} = {len};
                if ({is_err}) {{
                    ptr{i} = 0; len{i} = 0;
                    throw {take_object}({err});
                }}
                ",
            ));
            let ptr = js.local(format!("ptr{i}"));
            let len = js.local(format!("len{i}"));
            js.push(ptr);
            js.push(len);
        }

        Instruction::OptionString {
            mem,
            malloc,
            free,
            realloc,
            kind,
        } => {
            let func = js.cx.expose_pass_string_to_wasm(*mem);
            let i = js.tmp();
            let malloc = js.cx.wasm_export_of(*malloc);
            let val = js.pop();
            let realloc = js.cx.optional_func_arg(*realloc);
            let none = js.is_none(&val, *kind);
            let ptr = js.declare(
                "var",
                format!("ptr{i}"),
                format!("{none} ? 0 : {func}({val}, {malloc}{realloc})"),
            );
            let len = js.vector_len(&val, *kind);
            let len = js.declare("var", format!("len{i}"), len);
            let release = js.vector_release(&VectorKind::String, *mem, *free, &ptr, &len);
            js.release(release);
            js.push(ptr);
            js.push(len);
        }

        Instruction::OptionVector {
            kind,
            mem,
            malloc,
            free,
            option_kind,
        } => {
            let func = js.cx.pass_to_wasm_function(kind.clone(), *mem);
            let i = js.tmp();
            let malloc = js.cx.wasm_export_of(*malloc);
            let val = js.pop();
            js.assert_optional_array_like(&val, kind, *option_kind);
            let none = js.is_none(&val, *option_kind);
            let ptr = js.declare(
                "var",
                format!("ptr{i}"),
                format!("{none} ? 0 : {func}({val}, {malloc})"),
            );
            let len = js.vector_len(&val, *option_kind);
            let len = js.declare("var", format!("len{i}"), len);
            let release = js.vector_release(kind, *mem, *free, &ptr, &len);
            js.release(release);
            js.push(ptr);
            js.push(len);
        }

        Instruction::MutableSliceToMemory {
            kind,
            malloc,
            free,
            mem,
        } => {
            // Copy the contents of the typed array into wasm.
            let val = js.pop();
            js.assert_typed_array(&val, kind);
            let func = js.cx.pass_to_wasm_function(kind.clone(), *mem);
            let malloc = js.cx.wasm_export_of(*malloc);
            let i = js.tmp();
            let ptr = js.declare("var", format!("ptr{i}"), format!("{func}({val}, {malloc})"));
            let len = js.declare("var", format!("len{i}"), "WASM_VECTOR_LEN".into());
            // Then pass it the pointer and the length of where we copied it.
            let release = js.vector_release(kind, *mem, *free, &ptr, &len);
            js.release(release);
            js.push(ptr);
            js.push(len);
            // Then we give Wasm a reference to the original typed array, so that it can
            // update it with modifications made on the Wasm side before returning.
            js.push(val);
        }

        Instruction::BoolFromI32 => {
            let val = js.pop();
            js.push(format!("{val} !== 0"));
        }

        Instruction::ExternrefLoadOwned { table_and_drop } => {
            let take_object = if let Some((table, drop)) = *table_and_drop {
                js.cx
                    .expose_take_from_externref_table(table, drop)
                    .to_string()
            } else {
                js.cx.expose_take_object();
                "takeObject".to_string()
            };
            let val = js.pop();
            js.push(format!("{take_object}({val})"));
        }

        Instruction::StringFromChar => {
            let val = js.pop();
            js.push(format!("String.fromCodePoint({val})"));
        }

        Instruction::RustFromI32 { class } => {
            let val = js.pop();
            // `exported_classes` is keyed by the qualified JS identity, so
            // the resolved class string is the qualified name directly.
            let resolved_class = js.cx.resolve_class_name(class).to_string();
            match constructor {
                Some(name) if js.cx.resolve_class_name(name) == resolved_class => {
                    // Get the JS identifier for the class, which may be aliased
                    // if the name conflicts with a JS builtin (e.g., `Array` -> `Array2`)
                    let identifier = js.cx.require_class_identifier(class);
                    // Gather inheritance info (ancestors, own qualified name)
                    // before any mutable borrow for prelude emission.
                    let cls = js.cx.exported_classes.get(&resolved_class);
                    let participates = cls.is_some_and(|c| c.participates_in_inheritance);
                    // The map key *is* the qualified name post-#5154.
                    let own_qualified = resolved_class.clone();
                    // Per-class pointer suffix uses the class's auto-sanitized
                    // JS identifier (always a valid JS ident) rather than the
                    // user-facing js_name, which may contain hyphens or other
                    // chars that would break `obj.__wbg_ptr_<...>` syntax.
                    let own_ident = cls
                        .map(|c| c.identifier.clone())
                        .unwrap_or_else(|| resolved_class.clone());
                    // For each ancestor: (identifier, qualified_name).
                    // Nearest-first: ancestors[0] is the direct parent.
                    // identifier   -> per-class pointer field suffix
                    // qualified    -> upcast / free symbol names (match macro)
                    let ancestors: Vec<(String, String)> =
                        cls.map(|c| c.ancestors.clone()).unwrap_or_default();
                    // When reinit is enabled, define __wbg_inst as non-enumerable
                    // and non-configurable so it doesn't appear in serialization
                    // (e.g. toJSON) but remains writable for instance replacement.
                    let (ptr_assignment, register_data) = if participates {
                        let mut body = String::new();
                        body.push_str(&format!("this.__wbg_ptr = {val} >>> 0;\n"));
                        body.push_str(&format!("this.__wbg_ptr_{own_ident} = {val} >>> 0;\n"));
                        if js.cx.generate_reinit {
                            body.push_str(
                                "Object.defineProperty(this, '__wbg_inst', { value: __wbg_instance_id, writable: true });\n",
                            );
                        }
                        // Chain upcasts: each hop consumes the previous ptr.
                        let mut prev_ptr_expr = format!("{val} >>> 0");
                        let mut from_qualified = own_qualified.clone();
                        let mut token_parts: Vec<String> =
                            vec![format!("__wbg_ptr_{own_ident}: {val} >>> 0")];
                        for (idx, (anc_id, anc_qualified)) in ancestors.iter().enumerate() {
                            // Upcast symbol uses qualified_name on both
                            // sides; same convention as the macro after
                            // the `extends_js_class` / `extends_js_namespace`
                            // unification.
                            let sym = wasm_bindgen_shared::upcast_function(
                                &from_qualified,
                                anc_qualified,
                            );
                            let tmp = js.local(format!("__wbg_anc_{idx}"));
                            let sym = js.cx.wasm_export_ref(&sym);
                            body.push_str(&format!(
                                "const {tmp} = {sym}({prev_ptr_expr}) >>> 0;\n"
                            ));
                            body.push_str(&format!("this.__wbg_ptr_{anc_id} = {tmp};\n"));
                            token_parts.push(format!("__wbg_ptr_{anc_id}: {tmp}"));
                            prev_ptr_expr = tmp;
                            from_qualified = anc_qualified.clone();
                        }
                        let token = if js.cx.generate_reinit {
                            format!(
                                "{{ {}, instance: __wbg_instance_id }}",
                                token_parts.join(", ")
                            )
                        } else {
                            format!("{{ {} }}", token_parts.join(", "))
                        };
                        (body, token)
                    } else if js.cx.generate_reinit {
                        (
                            format!(
                                "\
                                this.__wbg_ptr = {val};
                                Object.defineProperty(this, '__wbg_inst', {{ value: __wbg_instance_id, writable: true }});
                                "
                            ),
                            format!("{{ ptr: {val}, instance: __wbg_instance_id }}"),
                        )
                    } else {
                        (
                            format!("this.__wbg_ptr = {val};"),
                            "this.__wbg_ptr".to_string(),
                        )
                    };

                    js.cx.body_refs.insert(format!("{identifier}Finalization"));
                    js.prelude(&format!(
                        "
                        {ptr_assignment}
                        {identifier}Finalization.register(this, {register_data}, this);
                        "
                    ));
                    js.push(String::from("this"));
                }
                Some(_) | None => {
                    let identifier = js.cx.require_class_wrap(class);
                    js.push(format!("{identifier}.__wrap({val})"));
                }
            }
        }

        Instruction::OptionRustFromI32 { class, kind } => {
            assert!(constructor.is_none());
            let val = js.pop();
            let identifier = js.cx.require_class_wrap(class);
            js.push(abi_option(
                &val,
                *kind,
                "0",
                "1",
                &format!("{identifier}.__wrap({val})"),
            ));
        }

        Instruction::CachedStringLoad {
            owned,
            mem,
            free,
            table,
        } => {
            let len = js.pop();
            let ptr = js.pop();
            let tmp = js.tmp();

            let get = js.cx.expose_get_cached_string_from_wasm(*mem, *table);

            js.prelude(&format!("var v{tmp} = {get}({ptr}, {len});"));

            if *owned {
                let free = js.cx.wasm_export_of(*free);
                js.prelude(&format!("if ({ptr} !== 0) {{ {free}({ptr}, {len}, 1); }}",));
            }

            let v = js.local(format!("v{tmp}"));
            js.push(v);
        }

        Instruction::TableGet => {
            let val = js.pop();
            // With externref the pass sinks every argument's `TableGet` into
            // wasm, leaving only an encoded cell's, read from memory in JS.
            match js.cx.aux.externref_table {
                Some(table) => {
                    let table = js.cx.export_name_of(table);
                    let table = js.cx.wasm_export_ref(&table);
                    js.push(format!("{table}.get({val})"));
                }
                None => {
                    js.cx.expose_get_object();
                    js.push(format!("getObject({val})"));
                }
            }
        }

        Instruction::Closure {
            adapter,
            nargs,
            mutable,
            dtor,
        } => {
            let b = js.pop();
            let a = js.pop();
            let wrapper = js.cx.export_adapter_name(*adapter);

            if matches!(js.cx.config.mode, OutputMode::Emscripten) {
                js.cx.adapter_deps.insert(wrapper.clone());
            }

            // TODO: further merge the heap and stack closure handling as
            // they're almost identical (by nature) except for ownership
            // integration.
            if let ClosureDtor::OwnClosure = dtor {
                // Persistent/owned closure with destructor
                let make_closure = if *mutable {
                    js.cx.expose_make_mut_closure();
                    "makeMutClosure"
                } else {
                    js.cx.expose_make_closure();
                    "makeClosure"
                };

                js.push(format!("{make_closure}({a}, {b}, {wrapper})"));
            } else {
                // Borrowed closure without destructor
                let i = js.tmp();
                js.local(format!("state{i}"));
                js.prelude(&format!("var state{i} = {{a: {a}, b: {b}}};"));
                let args = (0..*nargs)
                    .map(|i| format!("arg{i}"))
                    .collect::<Vec<_>>()
                    .join(", ");
                if *mutable {
                    // Mutable closures need protection against being called
                    // recursively, so ensure that we clear out one of the
                    // internal pointers while it's being invoked.
                    js.prelude(&format!(
                        "var cb{i} = ({args}) => {{
                            const a = state{i}.a;
                            state{i}.a = 0;
                            try {{
                                return {wrapper}(a, state{i}.b, {args});
                            }} finally {{
                                state{i}.a = a;
                            }}
                        }};",
                    ));
                } else {
                    js.prelude(&format!(
                        "var cb{i} = ({args}) => {wrapper}(state{i}.a, state{i}.b, {args});",
                    ));
                }

                match dtor {
                    ClosureDtor::OwnClosure => unreachable!(),
                    ClosureDtor::Immediate => {
                        // Wrapper for &dyn FnMut/&dyn Fn closure
                        // used as an argument to a JS function. Make sure to null out our
                        // internal pointers when we return back to Rust to
                        // ensure that any lingering references to the closure
                        // will fail immediately due to null pointers passed in
                        // to Rust.
                        js.finally(&format!("state{i}.a = 0;"));
                    }
                    ClosureDtor::Borrowed => {
                        // Borrowed closure from ScopedClosure::borrow/borrow_mut. Add
                        // _wbg_cb_unref to invalidate the closure at the end of
                        // the scoped block.
                        js.prelude(&format!("cb{i}._wbg_cb_unref = () => state{i}.a = 0;"));
                    }
                }
                let cb = js.local(format!("cb{i}"));
                js.push(cb);
            }
        }

        Instruction::VectorLoad {
            kind,
            mem,
            free,
            mode,
        } => {
            let len = js.pop();
            let ptr = js.pop();
            let f = js.cx.expose_get_vector_from_wasm(kind.clone(), *mem);
            // The data is freed below, so it can never be left as a view.
            // TODO(next major): default to `slice = transfer` here and in
            // `OptionVectorLoad`, once supported. It needs a view no other view
            // can be derived from, so that a finalizer can free the data:
            // https://github.com/tc39/proposal-limited-arraybuffer/issues/19.
            let mode = match mode {
                SeqValue::View => SeqValue::Copy,
                mode => *mode,
            };
            let load = seq_value_expr(format!("{f}({ptr}, {len})"), kind, mode);
            let i = js.tmp();
            let free = js.cx.wasm_export_of(*free);
            js.prelude(&format!("var v{i} = {load};"));
            js.prelude(&format!(
                "{free}({ptr}, {len} * {size}, {size});",
                size = kind.size()
            ));
            let v = js.local(format!("v{i}"));
            js.push(v)
        }

        Instruction::OptionVectorLoad {
            kind,
            mem,
            free,
            mode,
            option_kind,
        } => {
            let len = js.pop();
            let ptr = js.pop();
            let f = js.cx.expose_get_vector_from_wasm(kind.clone(), *mem);
            let mode = match mode {
                SeqValue::View => SeqValue::Copy,
                mode => *mode,
            };
            let load = seq_value_expr(format!("{f}({ptr}, {len})"), kind, mode);
            let i = js.tmp();
            let free = js.cx.wasm_export_of(*free);
            let init = empty_vector_init(&len, *option_kind);
            js.prelude(&format!("let v{i}{init};"));
            js.prelude(&format!("if ({ptr} !== 0) {{"));
            js.prelude(&format!("v{i} = {load};"));
            js.prelude(&format!(
                "{free}({ptr}, {len} * {size}, {size});",
                size = kind.size()
            ));
            js.prelude("}");
            let v = js.local(format!("v{i}"));
            js.push(v);
        }

        Instruction::EncodedSliceLoad {
            words,
            elem,
            mem,
            free,
            optional,
        } => {
            let len = js.pop();
            let ptr = js.pop();
            let i = js.tmp();
            let p = js.local(format!("p{i}"));
            let end = js.local(format!("end{i}"));
            let memory = js.cx.expose_dataview_memory(*mem);
            let memory = if js.cx.config.mode.emscripten() {
                memory.name.to_string()
            } else {
                format!("{memory}()")
            };
            // Decoding never calls into wasm, so memory cannot grow under the
            // loop and one view serves the whole buffer.
            let view = js.local(format!("view{i}"));
            let (fields, stride, align) = encoded_slice_layout(words)?;
            let reads = fields
                .iter()
                .map(|(offset, ty)| format!("{view}.get{ty}({p} + {offset}, true)"))
                .collect::<Vec<_>>();
            // Decode one element from its words with its own instructions,
            // into the loop body.
            let reads = reads
                .into_iter()
                .map(|expr| Value::Expr { expr, pure: false })
                .collect();
            let stack = std::mem::replace(&mut js.stack, reads);
            let prelude = std::mem::take(&mut js.prelude);
            for instr in elem {
                instruction(js, &instr.instr, log_error, constructor)?;
            }
            let value = js.pop();
            let body = render(&std::mem::replace(&mut js.prelude, prelude));
            js.stack = stack;
            let v = js.local(format!("v{i}"));
            let free = js.cx.wasm_export_of(*free);
            let coerce = js.cx.coerce_ptr_assign(&p);
            if let Some(kind) = optional {
                let init = empty_vector_init(&len, *kind);
                js.prelude(&format!("let {v}{init};\nif ({ptr} !== 0) {{\n{v} = [];"));
            } else {
                js.prelude(&format!("const {v} = [];"));
            }
            js.prelude(&format!(
                "
                let {p} = {ptr};
                {coerce}
                const {view} = {memory};
                for (const {end} = {p} + {len} * {stride}; {p} < {end}; {p} += {stride}) {{
                {body}{v}.push({value});
                }}
                {free}({ptr}, {len} * {stride}, {align});
                "
            ));
            if optional.is_some() {
                js.prelude("}");
            }
            js.push(v);
        }

        Instruction::EncodedSliceStore {
            words,
            elem,
            malloc,
            free,
            mem,
            optional,
            option_kind,
        } => {
            let val = js.pop();
            let i = js.tmp();
            let ptr = js.local(format!("ptr{i}"));
            let len = js.local(format!("len{i}"));
            let j = js.local(format!("j{i}"));
            let p = js.local(format!("p{i}"));
            let e = js.local(format!("e{i}"));
            let memory = js.cx.expose_dataview_memory(*mem);
            let memory = if js.cx.config.mode.emscripten() {
                memory.name.to_string()
            } else {
                format!("{memory}()")
            };
            // Encoding never calls into wasm, so the view taken after the
            // allocation serves the whole buffer.
            let view = js.local(format!("view{i}"));
            let (fields, stride, align) = encoded_slice_layout(words)?;
            // Encode one element into its words with its own instructions,
            // into the loop body.
            // The element reads the loop's local, so it's never hoisted
            // ahead of it; the guard belongs to the enclosing arguments.
            let guard = js.guard.take();
            let stack = std::mem::replace(&mut js.stack, vec![Value::Local(e.clone())]);
            let prelude = std::mem::take(&mut js.prelude);
            for instr in elem {
                instruction(js, &instr.instr, log_error, constructor)?;
            }
            let values = std::mem::replace(&mut js.stack, stack);
            let mut body = render(&std::mem::replace(&mut js.prelude, prelude));
            debug_assert!(js.guard.is_none(), "an encoded element allocated");
            js.guard = guard;
            for ((offset, ty), value) in fields.iter().zip(values) {
                body.push_str(&format!("{view}.set{ty}({p} + {offset}, {value}, true);\n"));
            }
            let malloc = js.cx.wasm_export_of(*malloc);
            let free = js.cx.wasm_export_of(*free);
            let coerce = js.cx.coerce_ptr_suffix();
            let alloc = format!("{malloc}({len} * {stride}, {align}){coerce}");
            if *optional {
                js.declare("let", ptr.clone(), "0".into());
                // A nullable `null` buffer is the null pointer with the
                // `null` handle as its length.
                let empty_len = if option_kind.nullable() {
                    format!("{val} === null ? {NULL_HANDLE} : 0")
                } else {
                    "0".into()
                };
                js.declare("let", len.clone(), empty_len);
                let some = js.is_some(&val, *option_kind);
                js.prelude(&format!(
                    "if ({some}) {{\n{len} = {val}.length;\n{ptr} = {alloc};"
                ));
            } else {
                js.declare("const", len.clone(), format!("{val}.length"));
                js.declare("const", ptr.clone(), alloc);
            }
            // An element encoder may throw (an invalid `char`, say), which
            // the guard frees the buffer for.
            js.release(format!(
                "if ({ptr}) {free}({ptr}, {len} * {stride}, {align});"
            ));
            js.prelude(&format!(
                "
                const {view} = {memory};
                for (let {j} = 0; {j} < {len}; {j}++) {{
                const {e} = {val}[{j}];
                const {p} = {ptr} + {j} * {stride};
                {body}}}
                "
            ));
            if *optional {
                js.prelude("}");
            }
            js.push(ptr);
            js.push(len);
        }

        Instruction::View { kind, mem, mode } => {
            let len = js.pop();
            let ptr = js.pop();
            let f = view_from_wasm(js, kind, *mem);
            js.push(seq_value_expr(format!("{f}({ptr}, {len})"), kind, *mode));
        }

        Instruction::OptionView {
            kind,
            mem,
            mode,
            option_kind,
        } => {
            let len = js.pop();
            let ptr = js.pop();
            let f = view_from_wasm(js, kind, *mem);
            let view = seq_value_expr(format!("{f}({ptr}, {len})"), kind, *mode);
            let empty = empty_vector_value(&len, *option_kind);
            js.push(format!("{ptr} === 0 ? {empty} : {view}"));
        }

        Instruction::OptionF64Sentinel { kind } => {
            let val = js.pop();
            js.push(abi_option(
                &val,
                *kind,
                F64_OPTION_SENTINEL,
                F64_NULL_SENTINEL,
                &val,
            ));
        }

        Instruction::OptionU32Sentinel { kind } => {
            let val = js.pop();
            js.push(abi_option(
                &val,
                *kind,
                U32_OPTION_SENTINEL,
                U32_NULL_SENTINEL,
                &val,
            ));
        }

        Instruction::ToOptionNative { ty, signed, kind } => {
            let val = js.pop();
            let present = js.pop();
            let value = if *signed {
                val
            } else {
                match ty {
                    ValType::I32 => format!("{val} >>> 0"),
                    ValType::I64 => format!("BigInt.asUintN(64, {val})"),
                    _ => unreachable!("unsigned non-integer"),
                }
            };
            js.push(abi_option(&present, *kind, "0", "2", &value));
        }

        Instruction::OptionBoolFromI32 { kind } => {
            let val = js.pop();
            js.push(abi_option(
                &val,
                *kind,
                U32_OPTION_SENTINEL,
                U32_NULL_SENTINEL,
                &format!("{val} !== 0"),
            ));
        }

        Instruction::OptionCharFromI32 { kind } => {
            let val = js.pop();
            js.push(abi_option(
                &val,
                *kind,
                U32_OPTION_SENTINEL,
                U32_NULL_SENTINEL,
                &format!("String.fromCodePoint({val})"),
            ));
        }

        Instruction::OptionEnumFromF64 { hole, kind } => {
            let val = js.pop();
            js.push(abi_option(
                &val,
                *kind,
                &hole.to_string(),
                F64_NULL_SENTINEL,
                &val,
            ));
        }

        Instruction::I32FromNonNull => {
            let val = js.pop();
            js.assert_non_null(&val);
            js.push(val);
        }
    }
    Ok(())
}

/// The helper reading borrowed vector data of `kind`; for externref kinds, the
/// version that doesn't take ownership of the handles.
fn view_from_wasm(js: &mut JsBuilder, kind: &VectorKind, mem: walrus::MemoryId) -> MemView {
    match kind {
        VectorKind::Externref | VectorKind::NamedExternref(_) => {
            js.cx.expose_get_array_js_value_view_from_wasm(mem)
        }
        _ => js.cx.expose_get_vector_from_wasm(kind.clone(), mem),
    }
}

/// The layout of an encoded slice element's ABI `words`, each at its natural
/// alignment as in the `#[repr(C)]` ABI types the buffer holds: each word's
/// offset and `DataView` accessor suffix, the stride and the alignment.
fn encoded_slice_layout(
    words: &[AdapterType],
) -> Result<(Vec<(usize, &'static str)>, usize, usize), Error> {
    let mut fields = Vec::new();
    let mut stride: usize = 0;
    let mut align: usize = 1;
    for word in words {
        let (size, ty) = match word {
            AdapterType::I32 => (4, "Int32"),
            AdapterType::F32 => (4, "Float32"),
            AdapterType::I64 => (8, "BigInt64"),
            AdapterType::F64 => (8, "Float64"),
            _ => bail!("unsupported slice element word {word:?}"),
        };
        stride = stride.next_multiple_of(size);
        fields.push((stride, ty));
        stride += size;
        align = align.max(size);
    }
    Ok((fields, stride.next_multiple_of(align), align))
}

/// The JS value for the vector `load` of `kind` per `mode`. Only typed kinds
/// load as a view of wasm memory; string and externref loaders already build
/// a fresh value, which no mode changes.
fn seq_value_expr(load: String, kind: &VectorKind, mode: SeqValue) -> String {
    match (kind, mode) {
        (VectorKind::String | VectorKind::Externref | VectorKind::NamedExternref(_), _)
        | (_, SeqValue::View) => load,
        (_, SeqValue::Copy) => format!("{load}.slice()"),
        (_, SeqValue::Array) => format!("Array.from({load})"),
    }
}

enum Invocation {
    Core {
        id: walrus::FunctionId,
        export_id: Option<walrus::ExportId>,
        defer: bool,
    },
    Adapter(AdapterId),
}

impl Invocation {
    fn from(instr: &Instruction, module: &Module) -> Invocation {
        use Instruction::*;
        match instr {
            DeferFree { free, .. } => Invocation::Core {
                id: *free,
                export_id: None,
                defer: true,
            },

            CallExport(e) => match module.exports.get(*e).item {
                walrus::ExportItem::Function(id) => Invocation::Core {
                    id,
                    export_id: Some(*e),
                    defer: false,
                },
                _ => panic!("can only call exported function"),
            },

            CallAdapter(id) => Invocation::Adapter(*id),

            // this function is only called for the above instructions
            _ => unreachable!(),
        }
    }

    fn params_results(&self, cx: &Context) -> (usize, usize) {
        match self {
            Invocation::Core { id, .. } => {
                let ty = cx.module.funcs.get(*id).ty();
                let ty = cx.module.types.get(ty);
                (ty.params().len(), ty.results().len())
            }
            Invocation::Adapter(id) => {
                let adapter = &cx.wit.adapters[id];
                (adapter.params.len(), adapter.results.len())
            }
        }
    }

    fn invoke(
        &self,
        cx: &mut Context,
        args: &[String],
        prelude: &mut String,
        log_error: &mut bool,
        guard: &mut ExportGuard,
    ) -> Result<String, Error> {
        match self {
            Invocation::Core {
                id,
                export_id,
                defer,
            } => {
                let name = match export_id {
                    Some(eid) => cx.module.exports.get(*eid).name.clone(),
                    None => cx.export_name_of(*id),
                };
                let accessor = cx.wasm_export_ref(&name);
                // Only wrap the main export call (non-deferred) with
                // `WebAssembly.promising`.  Deferred calls like `__wbindgen_free`
                // must remain plain calls — they are not JSPI exports and
                // wrapping them causes them to return a discarded Promise instead of
                // running synchronously as expected.
                if cx.current_adapter_jspi && !defer {
                    // Emit a module-level lazy cache variable and wrap the
                    // call with `WebAssembly.promising` so the fiber can
                    // suspend via JSPI. On emscripten the cache variable must
                    // be its own library symbol (module-scope `let`s aren't
                    // preserved there); the `intrinsic` helper handles both.
                    let cache_var = format!(
                        "__wbg_jspi_{}",
                        name.replace(|c: char| !c.is_ascii_alphanumeric(), "_")
                    );
                    let decl = if matches!(cx.config.mode, OutputMode::Emscripten) {
                        Cow::Borrowed("undefined")
                    } else {
                        Cow::Owned(format!("let {cache_var};"))
                    };
                    cx.intrinsic(Cow::Owned(cache_var.clone()), Some(&cache_var), decl, &[]);
                    let raw = cx.raw_wasm_export_ref(&name);
                    Ok(format!(
                        "({cache_var} ??= WebAssembly.promising({raw}))({})",
                        args.join(", ")
                    ))
                } else {
                    Ok(format!("{accessor}({})", args.join(", ")))
                }
            }
            Invocation::Adapter(id) => {
                let adapter = &cx.wit.adapters[id];
                let kind = match adapter.kind {
                    AdapterKind::Import { kind, .. } => kind,
                    AdapterKind::Local { .. } => {
                        bail!("adapter-to-adapter calls not supported yet");
                    }
                };
                let import = &cx.aux.import_map[id];
                let variadic = cx.aux.imports_with_variadic.contains(id);
                if cx.import_never_log_error(import) {
                    *log_error = false;
                }
                if cx.import_never_handle_error(import) {
                    *guard = ExportGuard::None;
                }
                // Label manufactured bindings whose name says nothing about what
                // they bind. A `experimental_generic_mono` monomorphisation is emitted as
                // `__wbindgen_generic_<hash>`, so without this the glue is a wall of
                // near-identical anonymous shims.
                if let Some(comment) = cx.aux.import_comments.get(id) {
                    writeln!(prelude, "// {comment}")?;
                }
                cx.invoke_import(import, kind, args, variadic, prelude)
            }
        }
    }

    fn defer(&self) -> bool {
        match self {
            Invocation::Core { defer, .. } => *defer,
            _ => false,
        }
    }
}

#[derive(Debug, Clone, Copy)]
pub(crate) enum TypePosition {
    Argument,
    Return,
}

pub(crate) fn adapter2ts(
    ty: &AdapterType,
    position: TypePosition,
    dst: &mut String,
    refs: Option<&mut HashSet<TsReference>>,
    name_map: &HashMap<String, String>,
    typed_array_buffers: bool,
) {
    match ty {
        AdapterType::I32
        | AdapterType::S8
        | AdapterType::S16
        | AdapterType::S32
        | AdapterType::U8
        | AdapterType::U16
        | AdapterType::U32
        | AdapterType::F32
        | AdapterType::F64
        | AdapterType::NonNull => dst.push_str("number"),
        AdapterType::I64
        | AdapterType::S64
        | AdapterType::U64
        | AdapterType::S128
        | AdapterType::U128 => dst.push_str("bigint"),
        AdapterType::String => dst.push_str("string"),
        AdapterType::Externref => dst.push_str("any"),
        AdapterType::Bool => dst.push_str("boolean"),
        AdapterType::Vector(kind) => match kind {
            VectorKind::NamedExternref(name) => {
                let resolved = name_map.get(name).map(|s| s.as_str()).unwrap_or(name);
                if is_valid_ident(resolved) {
                    dst.push_str(&format!("{resolved}[]"));
                } else {
                    dst.push_str(&format!("({resolved})[]"));
                }
            }
            VectorKind::String | VectorKind::Externref => dst.push_str(&kind.js_ty()),
            _ => {
                dst.push_str(&kind.js_ty());
                // Owned typed-array returns are always copied out of wasm
                // memory into a fresh, non-shared `ArrayBuffer`.
                if typed_array_buffers && matches!(position, TypePosition::Return) {
                    dst.push_str("<ArrayBuffer>");
                }
                // Arguments are copied into wasm memory, which works the same
                // for a plain array of the element type.
                if let (TypePosition::Argument, Some(element)) =
                    (position, kind.plain_array_element_ty())
                {
                    dst.push_str(&format!(" | {element}[]"));
                }
            }
        },
        AdapterType::Array(elem) => {
            let mut elem_ty = String::new();
            adapter2ts(
                elem,
                position,
                &mut elem_ty,
                refs,
                name_map,
                typed_array_buffers,
            );
            if is_valid_ident(&elem_ty) {
                dst.push_str(&format!("{elem_ty}[]"));
            } else {
                dst.push_str(&format!("({elem_ty})[]"));
            }
        }
        AdapterType::MutableSlice(kind) => dst.push_str(&kind.js_ty()),
        AdapterType::Option { ty, kind } => {
            adapter2ts(ty, position, dst, refs, name_map, typed_array_buffers);
            dst.push_str(match (position, kind) {
                (TypePosition::Argument, OptionKind::Lenient) | (_, OptionKind::OptionNullable) => {
                    " | null | undefined"
                }
                (_, OptionKind::Nullable) => " | null",
                _ => " | undefined",
            });
        }
        AdapterType::NamedExternref(name) => dst.push_str(name),
        AdapterType::Struct(name) | AdapterType::Enum(name) => {
            let resolved = name_map.get(name).map(|s| s.as_str()).unwrap_or(name);
            dst.push_str(resolved);
        }
        AdapterType::StringEnum(name) => {
            if let Some(refs) = refs {
                refs.insert(TsReference::StringEnum(name.clone()));
            }

            dst.push_str(name);
        }
        AdapterType::DynamicUnion(name) => {
            if let Some(refs) = refs {
                refs.insert(TsReference::DynamicUnion(name.clone()));
            }

            dst.push_str(name);
        }
        AdapterType::Function => dst.push_str("any"),
    }
}

#[test]
fn encoded_slice_layout_matches_repr_c() {
    let layout = |words: &[AdapterType]| encoded_slice_layout(words).unwrap();
    assert_eq!(layout(&[AdapterType::I32]), (vec![(0, "Int32")], 4, 4));
    assert_eq!(
        layout(&[AdapterType::F64, AdapterType::F64]),
        (vec![(0, "Float64"), (8, "Float64")], 16, 8)
    );
    assert_eq!(
        layout(&[AdapterType::I32, AdapterType::F64]),
        (vec![(0, "Int32"), (8, "Float64")], 16, 8)
    );
}
